window.MG_LAZY_DATA["data/lazy/owner-courses/b334-d23d914a5dbf978d.json"]={sha256:"d23d914a5dbf978dd9beb26d7f6b16efc465221ec270c415f6be1c22bfc39cc6",value:{"id":"b334","title":"墨爾本地鐵隧道計畫","titleEn":"Melbourne Metro Tunnel project","category":"rail","kind":"course","status":"guided","contentStatus":"reviewable-educational-curriculum","summary":"以墨爾本地鐵隧道從建設到接入營運網路的背景，建立新站、隧道及既有郊區鐵路協同運轉的教學案例。學徒把施工沉陷、試驗紀錄、進路切換及轉乘時間相連，分開首次載客與完整班表整合兩個系統狀態。","summaryEn":"Use the Melbourne Metro Tunnel’s transition from construction to network operation to construct a teaching case joining new stations and tunnels to suburban railways. Link construction movement, test records, route switching and transfer time. Treat the first passenger opening and full timetable integration as distinct system states with different acceptance and operating evidence.","scope":"依公開工程原理、官方資料與規範架構編寫的原創教學；步驟是可驗證的學習任務與假想算例，不是設計圖說、施工計畫、軌道進入、牽引供電隔離或列車營運許可，也不是任何專案的設計文件。數值均為教學假設或公開資料，實際工程須由合格技師依規範與實測資料重新計算並簽證。","scopeEn":"Original teaching built from public engineering principles, official sources and code frameworks. Steps are verifiable learning tasks and hypothetical exercises, not design drawings, method statements, track-access, traction-power isolation or train-operation permits, or any project's design documents. Numbers are teaching assumptions or public data; real work must be recalculated and certified by qualified engineers using codes and measured data.","subcategory":"rail-metro","subcategoryTitle":"都會捷運與貨運","subcategoryTitleEn":"Urban metros and freight","learningTrack":"rail","learningSubdiscipline":"rail-metro","learningTags":["rail","rail-metro","station"],"architectureFamily":"rail-system","architectureNodes":[["路線與土建","Alignment and civil works"],["車輛與接觸","Vehicle and contact"],["牽引供電","Traction supply"],["行車控制","Movement control"],["車站與旅客","Stations and passengers"],["監測與維護","Monitoring and maintenance"]],"architectureEdges":[[0,1],[1,2],[2,3],[3,1],[3,4],[4,5],[5,0],[5,3]],"diagram":{"type":"rail-system","labels":["路線與土建","車輛與接觸","牽引供電","行車控制","車站與旅客"],"labelsEn":["Alignment and civil works","Vehicle and contact","Traction supply","Movement control","Stations and passengers"],"original":true,"notToScale":true},"workedExample":{"title":"原創假想算例與邊界","titleEn":"Original hypothetical example and boundaries","text":"整合原創算例：單元 1 得 work_length=551 m；單元 2 得 residual=5.091414 mm；單元 3 得 gradient=0.63 mm/m。上述三個結果使用各單元明示的不同邊界，不能任意相加或視為實際工程實測值。以第一單元 setup 的擾動測試，結果改為 532.1 m；學徒需先比較單位、敏感度和假設，再決定是否要細化模型。以墨爾本地鐵隧道從建設到接入營運網路的背景，建立新站、隧道及既有郊區鐵路協同運轉的教學案例。學徒把施工沉陷、試驗紀錄、進路切換及轉乘時間相連，分開首次載客與完整班表整合兩個系統狀態。 最終交付應保留原始輸入、測點時間戳、誤差範圍與無法由簡化式證明的結論。","textEn":"Integrated original exercise: unit 1 gives work_length=551 m; unit 2 gives residual=5.091414 mm; unit 3 gives gradient=0.63 mm/m. These three results use different explicit boundaries and must not be added or presented as measurements of the real railway. Perturbing setup in the first unit changes its result to 532.1 m. Compare units, sensitivity and assumptions before deciding which model needs refinement. Use the Melbourne Metro Tunnel’s transition from construction to network operation to construct a teaching case joining new stations and tunnels to suburban railways. Link construction movement, test records, route switching and transfer time. Treat the first passenger opening and full timetable integration as distinct system states with different acceptance and operating evidence. The final submission should retain original inputs, measurement timestamps, uncertainty ranges and conclusions that the simplified expressions cannot establish.","assumptions":"數值是本課自行設定的教學假設，不代表任何專案的設計值、量測值或規範允許值；改變系統邊界或荷載組合後必須重算。","assumptionsEn":"Inputs are teaching assumptions, not any project's design values, measurements or code allowances; recalculate after changing the system boundary or load combination.","sourceScope":"原創數值練習；來源支援公開原理與工程背景，不宣稱來源提供這組數據。","sourceScopeEn":"Original numerical exercise; sources support public principles and project context, not these numbers."},"depth":5,"languageCoverage":["zh-TW","en"],"simulationOnly":true,"educationEdition":16,"enrichmentVersion":16,"stages":[{"id":"b334-v16-s1","title":"施工窗口與可完成工作量與控制網與獨立量測殘差","titleEn":"Possession window and achievable work & Survey control and independent residuals","description":"本階段聚焦「施工窗口與可完成工作量」與「控制網與獨立量測殘差」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Possession window and achievable work\" and \"Survey control and independent residuals\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b334-v16-01","title":"施工窗口與可完成工作量：機制與系統路徑","titleEn":"Possession window and achievable work: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":[],"objective":"說明「施工窗口與可完成工作量」如何影響墨爾本地鐵隧道計畫的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Possession window and achievable work” governs forces, deformation, flow or signals in “Melbourne Metro Tunnel project”, and map the relevant inputs, transfer paths and boundaries.","instruction":"夜間施工窗口需先扣除封鎖確認、隔離、運入及恢復測試時間，剩餘時間才可進行實際工作。提高施工速度不一定提高總產出，若撤場與驗收成為關鍵路徑，必須先調整作業協調。 可施工時間等於總窗口扣掉保護設置、測試及還路等必要活動。這些活動可能有不可重疊的安全依賴；趕工不能直接刪除，應以資源和先後順序改變排程。 把接網施工窗口與全線班表轉換視為不同的交接事件。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「施工窗口與可完成工作量」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A night possession must allow for protection, isolation, access and restoration testing before productive work begins. Higher work rate does not always increase output if clearance and acceptance dominate the critical path. Coordination of dependencies may matter more than nominal production speed. Usable work time equals the possession window minus protection, testing and handback activities. These can have nonoverlapping safety dependencies and cannot simply be deleted to accelerate work. Change scheduling through resources and legitimate task order. Treat the connection possession and the complete timetable transition as separate handover events. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Possession window and achievable work” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：window=240 min; setup=47.25 min; restore=55 min; rate=4 m/min；計算：work_length=(window-setup-restore)*rate=551 m。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: window=240 min; setup=47.25 min; restore=55 min; rate=4 m/min; calculation: work_length=(window-setup-restore)*rate=551 m.","failure":"常見誤解：「施工窗口全長都可以直接乘以施工速度當成可完成量」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"The entire possession duration can be multiplied by work rate to obtain achievable production.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「施工窗口與可完成工作量」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Possession window and achievable work”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b334-v16-01-k1","title":"施工窗口與可完成工作量","titleEn":"Possession window and achievable work","text":"夜間施工窗口需先扣除封鎖確認、隔離、運入及恢復測試時間，剩餘時間才可進行實際工作。提高施工速度不一定提高總產出，若撤場與驗收成為關鍵路徑，必須先調整作業協調。","textEn":"A night possession must allow for protection, isolation, access and restoration testing before productive work begins. Higher work rate does not always increase output if clearance and acceptance dominate the critical path.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-01-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：施工窗口全長都可以直接乘以施工速度當成可完成量 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: The entire possession duration can be multiplied by work rate to obtain achievable production. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"關於「施工窗口與可完成工作量」，下列哪一項敘述正確？","questionEn":"Which statement about \"Possession window and achievable work\" is correct?","options":["施工窗口全長都可以直接乘以施工速度當成可完成量","夜間施工窗口需先扣除封鎖確認、隔離、運入及恢復測試時間，剩餘時間才可進行實際工作。","兩台儀器量得同樣座標就證明座標絕對正確"],"optionsEn":["The entire possession duration can be multiplied by work rate to obtain achievable production.","A night possession must allow for protection, isolation, access and restoration testing before productive work begins.","Matching coordinates from two instruments prove absolute coordinate accuracy."],"answer":1,"explanation":"夜間施工窗口需先扣除封鎖確認、隔離、運入及恢復測試時間，剩餘時間才可進行實際工作。 其餘選項是常見誤解。","explanationEn":"A night possession must allow for protection, isolation, access and restoration testing before productive work begins. The other options are common misconceptions."},"unit":1,"unitFacet":"mechanism","order":1,"sequence":1},{"id":"b334-v16-02","title":"施工窗口與可完成工作量：定量估算","titleEn":"Possession window and achievable work: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-01"],"objective":"以數值模型估算「施工窗口與可完成工作量」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Possession window and achievable work” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：window=240 min; setup=47.25 min; restore=55 min; rate=4 m/min；計算：work_length=(window-setup-restore)*rate=551 m。敏感度：setup 單獨增加百分之十至 51.975 min，其餘固定，結果為 532.1 m。模型邊界：固定速度與確定性窗口；不含返工、設備故障和分段驗收。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: window=240 min; setup=47.25 min; restore=55 min; rate=4 m/min; calculation: work_length=(window-setup-restore)*rate=551 m. Sensitivity: setup, increase this input alone by ten percent, to 51.975 min, with all other inputs fixed, gives 532.1 m. Model boundary: Fixed production rate and deterministic window; rework, equipment failure and phased acceptance are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：按事件紀錄封鎖、確認隔離、進場、工作結束與試驗完成時間，用實際有效工作時間計算產率。","observationEn":"How to cross-check: Log possession, isolation confirmation, access, work completion and final testing, then calculate productivity from actual effective work time.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b334-v16-02-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：window=240 min; setup=47.25 min; restore=55 min; rate=4 m/min；計算：work_length=(window-setup-restore)*rate=551 m。敏感度：setup 單獨增加百分之十至 51.975 min，其餘固定，結果為 532.1 m。模型邊界：固定速度與確定性窗口；不含返工、設備故障和分段驗收。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: window=240 min; setup=47.25 min; restore=55 min; rate=4 m/min; calculation: work_length=(window-setup-restore)*rate=551 m. Sensitivity: setup, increase this input alone by ten percent, to 51.975 min, with all other inputs fixed, gives 532.1 m. Model boundary: Fixed production rate and deterministic window; rework, equipment failure and phased acceptance are excluded.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-02-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"依「施工窗口與可完成工作量」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Possession window and achievable work\", which statement holds?","options":["注入漿量超過幾何空隙體積就能證明沒有殘留空洞","兩個定位來源彼此一致就能保證定位沒有共同偏差","原創假想算例，全部輸入均非本工程操作參數：window=240 min; setup=47.25 min; restore=55 min; rate=4 m/min。"],"optionsEn":["Injecting more than the geometric void volume proves that no void remains.","Agreement between two position sources guarantees absence of common bias.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：window=240 min; setup=47.25 min; restore=55 min; rate=4 m/min；計算：work_length=(window-setup-restore)*rate=551 m。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: window=240 min; setup=47.25 min; restore=55 min; rate=4 m/min; calculation: work_length=(window-setup-restore)*rate=551 m. Keep units when recalculating."},"unit":1,"unitFacet":"model","order":2,"sequence":2},{"id":"b334-v16-03","title":"施工窗口與可完成工作量：試驗與驗證","titleEn":"Possession window and achievable work: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-02"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「施工窗口與可完成工作量」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Possession window and achievable work” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"按事件紀錄封鎖、確認隔離、進場、工作結束與試驗完成時間，用實際有效工作時間計算產率。 逐項記錄窗口開始、保護完成、施工完成與還路時刻，核對前置條件及實際資源。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Log possession, isolation confirmation, access, work completion and final testing, then calculate productivity from actual effective work time. Log possession start, protection completion, work completion and handback times, checking mandatory prerequisites and resources actually available. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：增加前置作業時間並加入一次返工，重畫關鍵路徑，區分可平行任務與必須完成後才可開放的檢查。 再以本單元 setup 的對照值重算 work_length，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Increase setup time and add one rework event, redraw the critical path, and distinguish parallel tasks from checks that must finish before reopening. Also recalculate work_length for the alternative setup value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：壓縮恢復測試時間可能掩蓋未完成檢查；低估撤場時間會造成延誤，不能把安全確認當成可任意削減的冗餘。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Compressing restoration tests can hide incomplete checks, while underestimated clearance causes delay; safety confirmation cannot be treated as arbitrary slack. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b334-v16-03-k1","title":"驗證方法","titleEn":"Verification method","text":"按事件紀錄封鎖、確認隔離、進場、工作結束與試驗完成時間，用實際有效工作時間計算產率。 逐項記錄窗口開始、保護完成、施工完成與還路時刻，核對前置條件及實際資源。","textEn":"Log possession, isolation confirmation, access, work completion and final testing, then calculate productivity from actual effective work time. Log possession start, protection completion, work completion and handback times, checking mandatory prerequisites and resources actually available.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-03-k2","title":"現場實務","titleEn":"Site practice","text":"增加前置作業時間並加入一次返工，重畫關鍵路徑，區分可平行任務與必須完成後才可開放的檢查。 再以本單元 setup 的對照值重算 work_length，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Increase setup time and add one rework event, redraw the critical path, and distinguish parallel tasks from checks that must finish before reopening. Also recalculate work_length for the alternative setup value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"要驗證「施工窗口與可完成工作量」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Possession window and achievable work\"?","options":["按事件紀錄封鎖、確認隔離、進場、工作結束與試驗完成時間，用實際有效工作時間計算產率。","量測時不必記錄溫度、速度、運行歷程與施工荷重，因為它們不會影響結果。","轉乘路線距離最短就一定適合所有旅客最快銜接"],"optionsEn":["Log possession, isolation confirmation, access, work completion and final testing, then calculate productivity from actual effective work time.","Temperature, speed, operating history and construction loads need not be recorded because they cannot affect the result.","The shortest transfer route necessarily gives every passenger the fastest connection."],"answer":0,"explanation":"按事件紀錄封鎖、確認隔離、進場、工作結束與試驗完成時間，用實際有效工作時間計算產率。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Log possession, isolation confirmation, access, work completion and final testing, then calculate productivity from actual effective work time. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":1,"unitFacet":"verification","order":3,"sequence":3},{"id":"b334-v16-04","title":"施工窗口與可完成工作量：失效診斷","titleEn":"Possession window and achievable work: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-03"],"objective":"從症狀倒推「施工窗口與可完成工作量」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Possession window and achievable work” and propose discriminating checks, corrective actions and prevention.","instruction":"壓縮恢復測試時間可能掩蓋未完成檢查；低估撤場時間會造成延誤，不能把安全確認當成可任意削減的冗餘。 施工完成不等於可還路，需保留檢查測試與解除保護時間。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Compressing restoration tests can hide incomplete checks, while underestimated clearance causes delay; safety confirmation cannot be treated as arbitrary slack. Work completion is not readiness for handback; retain inspection, testing and protection-removal time. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：把接網施工窗口與全線班表轉換視為不同的交接事件。","observationEn":"Link to the mechanism: Treat the connection possession and the complete timetable transition as separate handover events.","failure":"誤判風險：若相信「施工窗口全長都可以直接乘以施工速度當成可完成量」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"The entire possession duration can be multiplied by work rate to obtain achievable production.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b334-v16-04-k1","title":"失效模式","titleEn":"Failure mode","text":"壓縮恢復測試時間可能掩蓋未完成檢查；低估撤場時間會造成延誤，不能把安全確認當成可任意削減的冗餘。 施工完成不等於可還路，需保留檢查測試與解除保護時間。","textEn":"Compressing restoration tests can hide incomplete checks, while underestimated clearance causes delay; safety confirmation cannot be treated as arbitrary slack. Work completion is not readiness for handback; retain inspection, testing and protection-removal time.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-04-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"在「施工窗口與可完成工作量」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Possession window and achievable work\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","壓縮恢復測試時間可能掩蓋未完成檢查；低估撤場時間會造成延誤，不能把安全確認當成可任意削減的冗餘。","兩台儀器量得同樣座標就證明座標絕對正確"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","Compressing restoration tests can hide incomplete checks, while underestimated clearance causes delay; safety confirmation cannot be treated as arbitrary slack.","Matching coordinates from two instruments prove absolute coordinate accuracy."],"answer":1,"explanation":"壓縮恢復測試時間可能掩蓋未完成檢查；低估撤場時間會造成延誤，不能把安全確認當成可任意削減的冗餘。 需以量測區分可能原因。","explanationEn":"Compressing restoration tests can hide incomplete checks, while underestimated clearance causes delay; safety confirmation cannot be treated as arbitrary slack. Discriminate candidate causes by measurement."},"unit":1,"unitFacet":"failure","order":4,"sequence":4},{"id":"b334-v16-05","title":"控制網與獨立量測殘差：機制與系統路徑","titleEn":"Survey control and independent residuals: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-04"],"objective":"說明「控制網與獨立量測殘差」如何影響墨爾本地鐵隧道計畫的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Survey control and independent residuals” governs forces, deformation, flow or signals in “Melbourne Metro Tunnel project”, and map the relevant inputs, transfer paths and boundaries.","instruction":"兩套獨立量測可用座標差的平方和開根號描述平面殘差，但這只是對照量而不是絕對準確度。共同基點錯誤會同時影響兩套結果，控制網需要閉合檢查及外部基準才能發現系統偏差。 兩座標差的歐氏長度表示平面殘差大小，不是隨機標準差。先把兩套座標轉到相同基準和單位，再檢查各方向偏差；共同平移可能讓相對殘差很小但絕對位置仍錯。 以固定外部基準重複測量，區分儀器誤差和真實位移。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「控制網與獨立量測殘差」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"The root-sum-square of coordinate differences describes planar residual between independent measurements, not absolute accuracy. A shared control-point error affects both results. Network closure and an external datum are needed to reveal systematic bias that agreement alone can conceal. The Euclidean length of two coordinate differences measures planar residual, not random standard deviation. Transform both coordinate sets to one datum and unit before inspecting directional differences. Common translation can leave a small relative residual while absolute position remains wrong. Repeat surveys against a fixed external datum to separate instrument error from real movement. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Survey control and independent residuals” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：dx=0.00315 m; dy=0.004 m；計算：residual=(dx*dx+dy*dy)**0.5*1000=5.091414 mm。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: dx=0.00315 m; dy=0.004 m; calculation: residual=(dx*dx+dy*dy)**0.5*1000=5.091414 mm.","failure":"常見誤解：「兩台儀器量得同樣座標就證明座標絕對正確」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Matching coordinates from two instruments prove absolute coordinate accuracy.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「控制網與獨立量測殘差」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Survey control and independent residuals”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b334-v16-05-k1","title":"控制網與獨立量測殘差","titleEn":"Survey control and independent residuals","text":"兩套獨立量測可用座標差的平方和開根號描述平面殘差，但這只是對照量而不是絕對準確度。共同基點錯誤會同時影響兩套結果，控制網需要閉合檢查及外部基準才能發現系統偏差。","textEn":"The root-sum-square of coordinate differences describes planar residual between independent measurements, not absolute accuracy. A shared control-point error affects both results.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-05-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：兩台儀器量得同樣座標就證明座標絕對正確 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Matching coordinates from two instruments prove absolute coordinate accuracy. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"關於「控制網與獨立量測殘差」，下列哪一項敘述正確？","questionEn":"Which statement about \"Survey control and independent residuals\" is correct?","options":["兩台儀器量得同樣座標就證明座標絕對正確","兩端高程相同就能證明兩點之間沒有差異沉陷","兩套獨立量測可用座標差的平方和開根號描述平面殘差，但這只是對照量而不是絕對準確度。"],"optionsEn":["Matching coordinates from two instruments prove absolute coordinate accuracy.","Equal endpoint elevations prove there is no differential settlement between them.","The root-sum-square of coordinate differences describes planar residual between independent measurements, not absolute accuracy."],"answer":2,"explanation":"兩套獨立量測可用座標差的平方和開根號描述平面殘差，但這只是對照量而不是絕對準確度。 其餘選項是常見誤解。","explanationEn":"The root-sum-square of coordinate differences describes planar residual between independent measurements, not absolute accuracy. The other options are common misconceptions."},"unit":2,"unitFacet":"mechanism","order":5,"sequence":5},{"id":"b334-v16-06","title":"控制網與獨立量測殘差：定量估算","titleEn":"Survey control and independent residuals: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-05"],"objective":"以數值模型估算「控制網與獨立量測殘差」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Survey control and independent residuals” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：dx=0.00315 m; dy=0.004 m；計算：residual=(dx*dx+dy*dy)**0.5*1000=5.091414 mm。敏感度：dx 單獨增加百分之十至 0.003465 m，其餘固定，結果為 5.292091 mm。模型邊界：平面兩分量殘差；不含座標轉換協方差和垂直誤差。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: dx=0.00315 m; dy=0.004 m; calculation: residual=(dx*dx+dy*dy)**0.5*1000=5.091414 mm. Sensitivity: dx, increase this input alone by ten percent, to 0.003465 m, with all other inputs fixed, gives 5.292091 mm. Model boundary: Planar two-component residual; transformation covariance and vertical error are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：用獨立控制點做閉合觀測，記錄儀器溫度、氣壓改正與視線長度，將重複性和系統偏差分開報告。","observationEn":"How to cross-check: Close observations on independent controls, record instrument temperature, pressure correction and sight length, and report repeatability separately from systematic bias.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b334-v16-06-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：dx=0.00315 m; dy=0.004 m；計算：residual=(dx*dx+dy*dy)**0.5*1000=5.091414 mm。敏感度：dx 單獨增加百分之十至 0.003465 m，其餘固定，結果為 5.292091 mm。模型邊界：平面兩分量殘差；不含座標轉換協方差和垂直誤差。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: dx=0.00315 m; dy=0.004 m; calculation: residual=(dx*dx+dy*dy)**0.5*1000=5.091414 mm. Sensitivity: dx, increase this input alone by ten percent, to 0.003465 m, with all other inputs fixed, gives 5.292091 mm. Model boundary: Planar two-component residual; transformation covariance and vertical error are excluded.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-06-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"依「控制網與獨立量測殘差」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Survey control and independent residuals\", which statement holds?","options":["原創假想算例，全部輸入均非本工程操作參數：dx=0.00315 m; dy=0.004 m。","聯鎖只要正常路徑通過測試就不需要檢查衝突請求","降低目標速度時可忽略初速與目標速度的平方差"],"optionsEn":["Original hypothetical exercise.","Passing normal route tests removes the need to test conflicting requests.","Reducing target speed allows the squared-speed difference to be ignored."],"answer":0,"explanation":"原創假想算例，全部輸入均非本工程操作參數：dx=0.00315 m; dy=0.004 m；計算：residual=(dx*dx+dy*dy)**0.5*1000=5.091414 mm。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: dx=0.00315 m; dy=0.004 m; calculation: residual=(dx*dx+dy*dy)**0.5*1000=5.091414 mm. Keep units when recalculating."},"unit":2,"unitFacet":"model","order":6,"sequence":6},{"id":"b334-v16-07","title":"控制網與獨立量測殘差：試驗與驗證","titleEn":"Survey control and independent residuals: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-06"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「控制網與獨立量測殘差」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Survey control and independent residuals” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"用獨立控制點做閉合觀測，記錄儀器溫度、氣壓改正與視線長度，將重複性和系統偏差分開報告。 以反向觀測、閉合路線和外部基準交叉檢核，分開報告平面殘差與可疑共同偏差。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Close observations on independent controls, record instrument temperature, pressure correction and sight length, and report repeatability separately from systematic bias. Cross-check reversed observations, closed loops and external references, reporting planar residual separately from suspected shared bias. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：加入一個共同平移偏差，檢查兩儀器殘差與外部基準差異，提出能辨識系統誤差的控制網配置。 再以本單元 dx 的對照值重算 residual，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Add a shared translation bias, compare inter-instrument residual with error to an external datum, and propose a control network that can reveal systematic error. Also recalculate residual for the alternative dx value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：同一錯誤基點會讓兩台儀器一致偏移；長視線折光與站體熱變形也可能被誤認為施工偏差。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: One wrong datum can shift both instruments consistently; long-sight refraction and thermal movement can also be mistaken for construction error. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b334-v16-07-k1","title":"驗證方法","titleEn":"Verification method","text":"用獨立控制點做閉合觀測，記錄儀器溫度、氣壓改正與視線長度，將重複性和系統偏差分開報告。 以反向觀測、閉合路線和外部基準交叉檢核，分開報告平面殘差與可疑共同偏差。","textEn":"Close observations on independent controls, record instrument temperature, pressure correction and sight length, and report repeatability separately from systematic bias. Cross-check reversed observations, closed loops and external references, reporting planar residual separately from suspected shared bias.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-07-k2","title":"現場實務","titleEn":"Site practice","text":"加入一個共同平移偏差，檢查兩儀器殘差與外部基準差異，提出能辨識系統誤差的控制網配置。 再以本單元 dx 的對照值重算 residual，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Add a shared translation bias, compare inter-instrument residual with error to an external datum, and propose a control network that can reveal systematic error. Also recalculate residual for the alternative dx value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"要驗證「控制網與獨立量測殘差」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Survey control and independent residuals\"?","options":["沿用另一處鐵路設施或路線的量測結果，就可視為本工程已完成驗證。","用獨立控制點做閉合觀測，記錄儀器溫度、氣壓改正與視線長度，將重複性和系統偏差分開報告。","風機已經啟動就能證明隧道每一處濃度同樣下降"],"optionsEn":["Reusing results from another railway facility or route counts as verifying this structure.","Close observations on independent controls, record instrument temperature, pressure correction and sight length, and report repeatability separately from systematic bias.","A running fan proves concentration falls equally at every point in the tunnel."],"answer":1,"explanation":"用獨立控制點做閉合觀測，記錄儀器溫度、氣壓改正與視線長度，將重複性和系統偏差分開報告。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Close observations on independent controls, record instrument temperature, pressure correction and sight length, and report repeatability separately from systematic bias. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":2,"unitFacet":"verification","order":7,"sequence":7},{"id":"b334-v16-08","title":"控制網與獨立量測殘差：失效診斷","titleEn":"Survey control and independent residuals: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-07"],"objective":"從症狀倒推「控制網與獨立量測殘差」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Survey control and independent residuals” and propose discriminating checks, corrective actions and prevention.","instruction":"同一錯誤基點會讓兩台儀器一致偏移；長視線折光與站體熱變形也可能被誤認為施工偏差。 閉合良好仍可能全部同向漂移，須使用外部穩定基準。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"One wrong datum can shift both instruments consistently; long-sight refraction and thermal movement can also be mistaken for construction error. Good closure can coexist with common drift; an external stable reference remains necessary. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：以固定外部基準重複測量，區分儀器誤差和真實位移。","observationEn":"Link to the mechanism: Repeat surveys against a fixed external datum to separate instrument error from real movement.","failure":"誤判風險：若相信「兩台儀器量得同樣座標就證明座標絕對正確」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Matching coordinates from two instruments prove absolute coordinate accuracy.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b334-v16-08-k1","title":"失效模式","titleEn":"Failure mode","text":"同一錯誤基點會讓兩台儀器一致偏移；長視線折光與站體熱變形也可能被誤認為施工偏差。 閉合良好仍可能全部同向漂移，須使用外部穩定基準。","textEn":"One wrong datum can shift both instruments consistently; long-sight refraction and thermal movement can also be mistaken for construction error. Good closure can coexist with common drift; an external stable reference remains necessary.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-08-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"在「控制網與獨立量測殘差」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Survey control and independent residuals\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","兩端高程相同就能證明兩點之間沒有差異沉陷","同一錯誤基點會讓兩台儀器一致偏移；長視線折光與站體熱變形也可能被誤認為施工偏差。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","Equal endpoint elevations prove there is no differential settlement between them.","One wrong datum can shift both instruments consistently; long-sight refraction and thermal movement can also be mistaken for construction error."],"answer":2,"explanation":"同一錯誤基點會讓兩台儀器一致偏移；長視線折光與站體熱變形也可能被誤認為施工偏差。 需以量測區分可能原因。","explanationEn":"One wrong datum can shift both instruments consistently; long-sight refraction and thermal movement can also be mistaken for construction error. Discriminate candidate causes by measurement."},"unit":2,"unitFacet":"failure","order":8,"sequence":8}],"order":1},{"id":"b334-v16-s2","title":"沉陷差與軌道坡折與注漿量與空隙體積","titleEn":"Differential settlement and track kink & Grout volume and void account","description":"本階段聚焦「沉陷差與軌道坡折」與「注漿量與空隙體積」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Differential settlement and track kink\" and \"Grout volume and void account\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b334-v16-09","title":"沉陷差與軌道坡折：機制與系統路徑","titleEn":"Differential settlement and track kink: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-08"],"objective":"說明「沉陷差與軌道坡折」如何影響墨爾本地鐵隧道計畫的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Differential settlement and track kink” governs forces, deformation, flow or signals in “Melbourne Metro Tunnel project”, and map the relevant inputs, transfer paths and boundaries.","instruction":"均勻沉陷主要改變高程，短距離差異沉陷則改變軌道坡度和車輪動態荷載。兩端高差除以基長只給平均坡度，無法描述局部尖峰；需要多點剖面才能辨認曲率與變形長度。 相同端點坡度可以對應完全不同的中間形狀，因此坡度不能單獨表示軌道曲率。測點間距必須小於欲辨認的變形尺度，並將高程誤差相對於基長傳遞到坡度結果。 對街區及既有鐵路分別畫出沉陷剖面和坡折尺度。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「沉陷差與軌道坡折」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Uniform settlement mainly changes elevation, whereas differential settlement over a short distance alters track slope and dynamic wheel loading. End-to-end difference divided by baseline gives only an average gradient, not a local peak. A spatial profile is needed to identify curvature and deformation length. Identical endpoint gradient can hide very different intermediate shapes, so gradient alone cannot describe track curvature. Survey spacing must resolve the deformation length scale, and elevation uncertainty must be propagated relative to the baseline into the reported gradient. Plot settlement profiles and kink length scales separately for city blocks and existing tracks. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Differential settlement and track kink” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：drop=0.0126 m; baseline=20 m；計算：gradient=1000*drop/baseline=0.63 mm/m。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: drop=0.0126 m; baseline=20 m; calculation: gradient=1000*drop/baseline=0.63 mm/m.","failure":"常見誤解：「兩端高程相同就能證明兩點之間沒有差異沉陷」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Equal endpoint elevations prove there is no differential settlement between them.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「沉陷差與軌道坡折」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Differential settlement and track kink”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b334-v16-09-k1","title":"沉陷差與軌道坡折","titleEn":"Differential settlement and track kink","text":"均勻沉陷主要改變高程，短距離差異沉陷則改變軌道坡度和車輪動態荷載。兩端高差除以基長只給平均坡度，無法描述局部尖峰；需要多點剖面才能辨認曲率與變形長度。","textEn":"Uniform settlement mainly changes elevation, whereas differential settlement over a short distance alters track slope and dynamic wheel loading. End-to-end difference divided by baseline gives only an average gradient, not a local peak.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-09-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：兩端高程相同就能證明兩點之間沒有差異沉陷 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Equal endpoint elevations prove there is no differential settlement between them. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"關於「沉陷差與軌道坡折」，下列哪一項敘述正確？","questionEn":"Which statement about \"Differential settlement and track kink\" is correct?","options":["均勻沉陷主要改變高程，短距離差異沉陷則改變軌道坡度和車輪動態荷載。","兩端高程相同就能證明兩點之間沒有差異沉陷","注入漿量超過幾何空隙體積就能證明沒有殘留空洞"],"optionsEn":["Uniform settlement mainly changes elevation, whereas differential settlement over a short distance alters track slope and dynamic wheel loading.","Equal endpoint elevations prove there is no differential settlement between them.","Injecting more than the geometric void volume proves that no void remains."],"answer":0,"explanation":"均勻沉陷主要改變高程，短距離差異沉陷則改變軌道坡度和車輪動態荷載。 其餘選項是常見誤解。","explanationEn":"Uniform settlement mainly changes elevation, whereas differential settlement over a short distance alters track slope and dynamic wheel loading. The other options are common misconceptions."},"unit":3,"unitFacet":"mechanism","order":1,"sequence":9},{"id":"b334-v16-10","title":"沉陷差與軌道坡折：定量估算","titleEn":"Differential settlement and track kink: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-09"],"objective":"以數值模型估算「沉陷差與軌道坡折」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Differential settlement and track kink” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：drop=0.0126 m; baseline=20 m；計算：gradient=1000*drop/baseline=0.63 mm/m。敏感度：drop 單獨增加百分之十至 0.01386 m，其餘固定，結果為 0.693 mm/m。模型邊界：小變形平均坡度；不計車軌耦合動力或容許軌道幾何。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: drop=0.0126 m; baseline=20 m; calculation: gradient=1000*drop/baseline=0.63 mm/m. Sensitivity: drop, increase this input alone by ten percent, to 0.01386 m, with all other inputs fixed, gives 0.693 mm/m. Model boundary: Small-deformation average gradient; vehicle-track dynamics and permissible geometry limits are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：採用同一穩定水準基點反覆量測，保留溫度和施工時間，利用多點高程剖面區分整段平移、坡折與量測基點漂移。","observationEn":"How to cross-check: Repeat surveys against one stable datum, retain temperature and construction timing, and use multipoint profiles to separate translation, kinks and datum drift.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b334-v16-10-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：drop=0.0126 m; baseline=20 m；計算：gradient=1000*drop/baseline=0.63 mm/m。敏感度：drop 單獨增加百分之十至 0.01386 m，其餘固定，結果為 0.693 mm/m。模型邊界：小變形平均坡度；不計車軌耦合動力或容許軌道幾何。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: drop=0.0126 m; baseline=20 m; calculation: gradient=1000*drop/baseline=0.63 mm/m. Sensitivity: drop, increase this input alone by ten percent, to 0.01386 m, with all other inputs fixed, gives 0.693 mm/m. Model boundary: Small-deformation average gradient; vehicle-track dynamics and permissible geometry limits are excluded.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-10-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"依「沉陷差與軌道坡折」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Differential settlement and track kink\", which statement holds?","options":["兩個定位來源彼此一致就能保證定位沒有共同偏差","原創假想算例，全部輸入均非本工程操作參數：drop=0.0126 m; baseline=20 m。","轉乘路線距離最短就一定適合所有旅客最快銜接"],"optionsEn":["Agreement between two position sources guarantees absence of common bias.","Original hypothetical exercise.","The shortest transfer route necessarily gives every passenger the fastest connection."],"answer":1,"explanation":"原創假想算例，全部輸入均非本工程操作參數：drop=0.0126 m; baseline=20 m；計算：gradient=1000*drop/baseline=0.63 mm/m。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: drop=0.0126 m; baseline=20 m; calculation: gradient=1000*drop/baseline=0.63 mm/m. Keep units when recalculating."},"unit":3,"unitFacet":"model","order":2,"sequence":10},{"id":"b334-v16-11","title":"沉陷差與軌道坡折：試驗與驗證","titleEn":"Differential settlement and track kink: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-10"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「沉陷差與軌道坡折」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Differential settlement and track kink” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"採用同一穩定水準基點反覆量測，保留溫度和施工時間，利用多點高程剖面區分整段平移、坡折與量測基點漂移。 重複觀測同一測點並做閉合檢核，以另一穩定基準核對零點，報告高差與基長各自誤差。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Repeat surveys against one stable datum, retain temperature and construction timing, and use multipoint profiles to separate translation, kinks and datum drift. Repeat identical points with closure checks, verify zero against another stable reference, and report separate errors for elevation difference and baseline. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：構造端點相同但中間下陷的剖面，與直線坡度模型比較；提出足以辨識沉陷槽寬度的測點間距與複測頻率。 再以本單元 drop 的對照值重算 gradient，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Construct a profile with equal endpoints and an intermediate trough, compare it with a straight-gradient model, and propose spacing and repeat intervals able to resolve the trough. Also recalculate gradient for the alternative drop value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：基點本身下沉會讓全段看似正常；只量端點又會漏掉中間沉陷槽，兩種情況均可低估輪軌衝擊。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A settling datum can hide movement of the whole section, and endpoint-only measurement misses an intermediate trough; both may understate wheel-rail impact. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b334-v16-11-k1","title":"驗證方法","titleEn":"Verification method","text":"採用同一穩定水準基點反覆量測，保留溫度和施工時間，利用多點高程剖面區分整段平移、坡折與量測基點漂移。 重複觀測同一測點並做閉合檢核，以另一穩定基準核對零點，報告高差與基長各自誤差。","textEn":"Repeat surveys against one stable datum, retain temperature and construction timing, and use multipoint profiles to separate translation, kinks and datum drift. Repeat identical points with closure checks, verify zero against another stable reference, and report separate errors for elevation difference and baseline.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-11-k2","title":"現場實務","titleEn":"Site practice","text":"構造端點相同但中間下陷的剖面，與直線坡度模型比較；提出足以辨識沉陷槽寬度的測點間距與複測頻率。 再以本單元 drop 的對照值重算 gradient，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Construct a profile with equal endpoints and an intermediate trough, compare it with a straight-gradient model, and propose spacing and repeat intervals able to resolve the trough. Also recalculate gradient for the alternative drop value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"要驗證「沉陷差與軌道坡折」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Differential settlement and track kink\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","設備可用度高就表示所有安全風險一定很低","採用同一穩定水準基點反覆量測，保留溫度和施工時間，利用多點高程剖面區分整段平移、坡折與量測基點漂移。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","High equipment availability necessarily means every safety risk is low.","Repeat surveys against one stable datum, retain temperature and construction timing, and use multipoint profiles to separate translation, kinks and datum drift."],"answer":2,"explanation":"採用同一穩定水準基點反覆量測，保留溫度和施工時間，利用多點高程剖面區分整段平移、坡折與量測基點漂移。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Repeat surveys against one stable datum, retain temperature and construction timing, and use multipoint profiles to separate translation, kinks and datum drift. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":3,"unitFacet":"verification","order":3,"sequence":11},{"id":"b334-v16-12","title":"沉陷差與軌道坡折：失效診斷","titleEn":"Differential settlement and track kink: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-11"],"objective":"從症狀倒推「沉陷差與軌道坡折」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Differential settlement and track kink” and propose discriminating checks, corrective actions and prevention.","instruction":"基點本身下沉會讓全段看似正常；只量端點又會漏掉中間沉陷槽，兩種情況均可低估輪軌衝擊。 高差異常需先查基點，不能立刻推定路基局部下沉。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"A settling datum can hide movement of the whole section, and endpoint-only measurement misses an intermediate trough; both may understate wheel-rail impact. An unusual level difference requires a datum check before inferring local earthwork settlement. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：對街區及既有鐵路分別畫出沉陷剖面和坡折尺度。","observationEn":"Link to the mechanism: Plot settlement profiles and kink length scales separately for city blocks and existing tracks.","failure":"誤判風險：若相信「兩端高程相同就能證明兩點之間沒有差異沉陷」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Equal endpoint elevations prove there is no differential settlement between them.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b334-v16-12-k1","title":"失效模式","titleEn":"Failure mode","text":"基點本身下沉會讓全段看似正常；只量端點又會漏掉中間沉陷槽，兩種情況均可低估輪軌衝擊。 高差異常需先查基點，不能立刻推定路基局部下沉。","textEn":"A settling datum can hide movement of the whole section, and endpoint-only measurement misses an intermediate trough; both may understate wheel-rail impact. An unusual level difference requires a datum check before inferring local earthwork settlement.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-12-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"在「沉陷差與軌道坡折」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Differential settlement and track kink\" shows distress, which diagnosis is most reasonable?","options":["基點本身下沉會讓全段看似正常；只量端點又會漏掉中間沉陷槽，兩種情況均可低估輪軌衝擊。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","注入漿量超過幾何空隙體積就能證明沒有殘留空洞"],"optionsEn":["A settling datum can hide movement of the whole section, and endpoint-only measurement misses an intermediate trough; both may understate wheel-rail impact.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","Injecting more than the geometric void volume proves that no void remains."],"answer":0,"explanation":"基點本身下沉會讓全段看似正常；只量端點又會漏掉中間沉陷槽，兩種情況均可低估輪軌衝擊。 需以量測區分可能原因。","explanationEn":"A settling datum can hide movement of the whole section, and endpoint-only measurement misses an intermediate trough; both may understate wheel-rail impact. Discriminate candidate causes by measurement."},"unit":3,"unitFacet":"failure","order":4,"sequence":12},{"id":"b334-v16-13","title":"注漿量與空隙體積：機制與系統路徑","titleEn":"Grout volume and void account: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-12"],"objective":"說明「注漿量與空隙體積」如何影響墨爾本地鐵隧道計畫的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Grout volume and void account” governs forces, deformation, flow or signals in “Melbourne Metro Tunnel project”, and map the relevant inputs, transfer paths and boundaries.","instruction":"填充空隙所需漿量先由幾何空隙體積估算，再考慮損失與材料體積變化。注入量大不代表填充完整，因為漿液可能沿裂縫流失；壓力、流量與返漿紀錄必須互相對照。 此算例把空隙視為長乘寬乘均勻厚度的薄層，再乘假定餘量。它不是完整圓環幾何；若用於環隙局部展開，須說明薄層近似，且不能由注入總量推論填充均勻。 以假想隧道局部薄層空隙驗算注漿體積，保留超灌和漏失項。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「注漿量與空隙體積」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Required grout begins with geometric void volume and allowances for loss and volume change. A large injected volume does not prove complete filling because grout can escape through cracks. Pressure, flow and returns must be interpreted together to distinguish filling from loss. This example treats a void as length times width times uniform thickness with an assumed allowance. It is not full annular geometry. A locally unwrapped annulus requires an explicit thin-layer approximation, and total injection does not establish uniform filling. Check grout volume for a hypothetical local thin tunnel void, retaining excess and loss terms. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Grout volume and void account” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：length=20 m; width=2.5 m; gap=0.042 m; allowance=1.15 1；計算：grout_volume=length*width*gap*allowance=2.415 m^3。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: length=20 m; width=2.5 m; gap=0.042 m; allowance=1.15 1; calculation: grout_volume=length*width*gap*allowance=2.415 m^3.","failure":"常見誤解：「注入漿量超過幾何空隙體積就能證明沒有殘留空洞」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Injecting more than the geometric void volume proves that no void remains.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「注漿量與空隙體積」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Grout volume and void account”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b334-v16-13-k1","title":"注漿量與空隙體積","titleEn":"Grout volume and void account","text":"填充空隙所需漿量先由幾何空隙體積估算，再考慮損失與材料體積變化。注入量大不代表填充完整，因為漿液可能沿裂縫流失；壓力、流量與返漿紀錄必須互相對照。","textEn":"Required grout begins with geometric void volume and allowances for loss and volume change. A large injected volume does not prove complete filling because grout can escape through cracks.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-13-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：注入漿量超過幾何空隙體積就能證明沒有殘留空洞 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Injecting more than the geometric void volume proves that no void remains. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"關於「注漿量與空隙體積」，下列哪一項敘述正確？","questionEn":"Which statement about \"Grout volume and void account\" is correct?","options":["注入漿量超過幾何空隙體積就能證明沒有殘留空洞","填充空隙所需漿量先由幾何空隙體積估算，再考慮損失與材料體積變化。","聯鎖只要正常路徑通過測試就不需要檢查衝突請求"],"optionsEn":["Injecting more than the geometric void volume proves that no void remains.","Required grout begins with geometric void volume and allowances for loss and volume change.","Passing normal route tests removes the need to test conflicting requests."],"answer":1,"explanation":"填充空隙所需漿量先由幾何空隙體積估算，再考慮損失與材料體積變化。 其餘選項是常見誤解。","explanationEn":"Required grout begins with geometric void volume and allowances for loss and volume change. The other options are common misconceptions."},"unit":4,"unitFacet":"mechanism","order":5,"sequence":13},{"id":"b334-v16-14","title":"注漿量與空隙體積：定量估算","titleEn":"Grout volume and void account: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-13"],"objective":"以數值模型估算「注漿量與空隙體積」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Grout volume and void account” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：length=20 m; width=2.5 m; gap=0.042 m; allowance=1.15 1；計算：grout_volume=length*width*gap*allowance=2.415 m^3。敏感度：gap 單獨增加百分之十至 0.0462 m，其餘固定，結果為 2.6565 m^3。模型邊界：均勻幾何間隙與假設損失係數；不指定注漿壓力或現地工法。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: length=20 m; width=2.5 m; gap=0.042 m; allowance=1.15 1; calculation: grout_volume=length*width*gap*allowance=2.415 m^3. Sensitivity: gap, increase this input alone by ten percent, to 0.0462 m, with all other inputs fixed, gives 2.6565 m^3. Model boundary: Uniform geometric gap and assumed loss allowance; no injection pressure or field procedure is specified. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：核對批次體積、流量計及返漿量，將注入壓力與時間曲線同步，完成後以獨立檢測確認空隙分布。","observationEn":"How to cross-check: Reconcile batch volume, flow meter and returns, synchronise injection pressure over time, and verify void distribution afterward using an independent inspection method.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b334-v16-14-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：length=20 m; width=2.5 m; gap=0.042 m; allowance=1.15 1；計算：grout_volume=length*width*gap*allowance=2.415 m^3。敏感度：gap 單獨增加百分之十至 0.0462 m，其餘固定，結果為 2.6565 m^3。模型邊界：均勻幾何間隙與假設損失係數；不指定注漿壓力或現地工法。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: length=20 m; width=2.5 m; gap=0.042 m; allowance=1.15 1; calculation: grout_volume=length*width*gap*allowance=2.415 m^3. Sensitivity: gap, increase this input alone by ten percent, to 0.0462 m, with all other inputs fixed, gives 2.6565 m^3. Model boundary: Uniform geometric gap and assumed loss allowance; no injection pressure or field procedure is specified.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-14-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"依「注漿量與空隙體積」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Grout volume and void account\", which statement holds?","options":["降低目標速度時可忽略初速與目標速度的平方差","風機已經啟動就能證明隧道每一處濃度同樣下降","原創假想算例，全部輸入均非本工程操作參數：length=20 m; width=2.5 m; gap=0.042 m; allowance=1.15 1。"],"optionsEn":["Reducing target speed allows the squared-speed difference to be ignored.","A running fan proves concentration falls equally at every point in the tunnel.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：length=20 m; width=2.5 m; gap=0.042 m; allowance=1.15 1；計算：grout_volume=length*width*gap*allowance=2.415 m^3。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: length=20 m; width=2.5 m; gap=0.042 m; allowance=1.15 1; calculation: grout_volume=length*width*gap*allowance=2.415 m^3. Keep units when recalculating."},"unit":4,"unitFacet":"model","order":6,"sequence":14},{"id":"b334-v16-15","title":"注漿量與空隙體積：試驗與驗證","titleEn":"Grout volume and void account: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-14"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「注漿量與空隙體積」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Grout volume and void account” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"核對批次體積、流量計及返漿量，將注入壓力與時間曲線同步，完成後以獨立檢測確認空隙分布。 校對泵送流量計與漿液批次密度，分開累計注入、回流及廢棄量，核對薄層幾何尺寸。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Reconcile batch volume, flow meter and returns, synchronise injection pressure over time, and verify void distribution afterward using an independent inspection method. Calibrate pump flow and batch density, separately total injection, return and waste volumes, and verify the thin-layer dimensions. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：比較正常填充與沿裂縫漏失兩組流量壓力紀錄，做體積收支並提出能辨識兩者的獨立檢測。 再以本單元 gap 的對照值重算 grout_volume，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Compare flow-pressure records for normal filling and crack leakage, build a volume balance, and propose an independent inspection that distinguishes the two. Also recalculate grout_volume for the alternative gap value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：漏失會讓注入體積增加而空隙仍未填滿，局部封堵又會使壓力快速上升；僅憑達到預算漿量不能驗收。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Loss can increase injected volume while leaving a void unfilled, and local blockage can raise pressure rapidly; reaching the budgeted volume is not acceptance evidence. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b334-v16-15-k1","title":"驗證方法","titleEn":"Verification method","text":"核對批次體積、流量計及返漿量，將注入壓力與時間曲線同步，完成後以獨立檢測確認空隙分布。 校對泵送流量計與漿液批次密度，分開累計注入、回流及廢棄量，核對薄層幾何尺寸。","textEn":"Reconcile batch volume, flow meter and returns, synchronise injection pressure over time, and verify void distribution afterward using an independent inspection method. Calibrate pump flow and batch density, separately total injection, return and waste volumes, and verify the thin-layer dimensions.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-15-k2","title":"現場實務","titleEn":"Site practice","text":"比較正常填充與沿裂縫漏失兩組流量壓力紀錄，做體積收支並提出能辨識兩者的獨立檢測。 再以本單元 gap 的對照值重算 grout_volume，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Compare flow-pressure records for normal filling and crack leakage, build a volume balance, and propose an independent inspection that distinguishes the two. Also recalculate grout_volume for the alternative gap value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"要驗證「注漿量與空隙體積」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Grout volume and void account\"?","options":["核對批次體積、流量計及返漿量，將注入壓力與時間曲線同步，完成後以獨立檢測確認空隙分布。","不確定度太難估計，報告中只寫最佳值即可。","施工窗口全長都可以直接乘以施工速度當成可完成量"],"optionsEn":["Reconcile batch volume, flow meter and returns, synchronise injection pressure over time, and verify void distribution afterward using an independent inspection method.","Uncertainty is too hard to estimate, so the report may state only the best value.","The entire possession duration can be multiplied by work rate to obtain achievable production."],"answer":0,"explanation":"核對批次體積、流量計及返漿量，將注入壓力與時間曲線同步，完成後以獨立檢測確認空隙分布。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Reconcile batch volume, flow meter and returns, synchronise injection pressure over time, and verify void distribution afterward using an independent inspection method. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":4,"unitFacet":"verification","order":7,"sequence":15},{"id":"b334-v16-16","title":"注漿量與空隙體積：失效診斷","titleEn":"Grout volume and void account: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-15"],"objective":"從症狀倒推「注漿量與空隙體積」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Grout volume and void account” and propose discriminating checks, corrective actions and prevention.","instruction":"漏失會讓注入體積增加而空隙仍未填滿，局部封堵又會使壓力快速上升；僅憑達到預算漿量不能驗收。 達到預算漿量不等於填滿空隙，須查回流和漏失。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Loss can increase injected volume while leaving a void unfilled, and local blockage can raise pressure rapidly; reaching the budgeted volume is not acceptance evidence. Reaching the budgeted grout volume does not prove void filling; inspect returns and losses. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：以假想隧道局部薄層空隙驗算注漿體積，保留超灌和漏失項。","observationEn":"Link to the mechanism: Check grout volume for a hypothetical local thin tunnel void, retaining excess and loss terms.","failure":"誤判風險：若相信「注入漿量超過幾何空隙體積就能證明沒有殘留空洞」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Injecting more than the geometric void volume proves that no void remains.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b334-v16-16-k1","title":"失效模式","titleEn":"Failure mode","text":"漏失會讓注入體積增加而空隙仍未填滿，局部封堵又會使壓力快速上升；僅憑達到預算漿量不能驗收。 達到預算漿量不等於填滿空隙，須查回流和漏失。","textEn":"Loss can increase injected volume while leaving a void unfilled, and local blockage can raise pressure rapidly; reaching the budgeted volume is not acceptance evidence. Reaching the budgeted grout volume does not prove void filling; inspect returns and losses.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-16-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"在「注漿量與空隙體積」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Grout volume and void account\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","漏失會讓注入體積增加而空隙仍未填滿，局部封堵又會使壓力快速上升；僅憑達到預算漿量不能驗收。","聯鎖只要正常路徑通過測試就不需要檢查衝突請求"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Loss can increase injected volume while leaving a void unfilled, and local blockage can raise pressure rapidly.","Passing normal route tests removes the need to test conflicting requests."],"answer":1,"explanation":"漏失會讓注入體積增加而空隙仍未填滿，局部封堵又會使壓力快速上升；僅憑達到預算漿量不能驗收。 需以量測區分可能原因。","explanationEn":"Loss can increase injected volume while leaving a void unfilled, and local blockage can raise pressure rapidly; reaching the budgeted volume is not acceptance evidence. Discriminate candidate causes by measurement."},"unit":4,"unitFacet":"failure","order":8,"sequence":16}],"order":2},{"id":"b334-v16-s3","title":"互斥進路與真值驗證與里程融合與不確定度","titleEn":"Conflicting routes and truth-table verification & Position fusion and uncertainty","description":"本階段聚焦「互斥進路與真值驗證」與「里程融合與不確定度」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Conflicting routes and truth-table verification\" and \"Position fusion and uncertainty\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b334-v16-17","title":"互斥進路與真值驗證：機制與系統路徑","titleEn":"Conflicting routes and truth-table verification: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-16"],"objective":"說明「互斥進路與真值驗證」如何影響墨爾本地鐵隧道計畫的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Conflicting routes and truth-table verification” governs forces, deformation, flow or signals in “Melbourne Metro Tunnel project”, and map the relevant inputs, transfer paths and boundaries.","instruction":"聯鎖的核心是明確禁止衝突進路同時成立，安全條件需要由占用、道岔鎖閉和列車完整通過共同決定。狀態數隨布林輸入快速增加，真值表可檢查邏輯完整性，但不能代替時序與硬體故障分析。 布林組合數表示測試狀態空間的大小，並不代表每個狀態在現場都可達或安全。應把占用、道岔鎖閉和授權的邏輯關係明列，逐項證明危險組合會被拒絕。 對新隧道與既有線進路切換建立互鎖狀態和拒絕條件。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「互斥進路與真值驗證」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Interlocking explicitly excludes simultaneous conflicting routes. Occupancy, locked points and complete train passage jointly determine permissive conditions. Boolean input combinations grow rapidly; a truth table checks logical coverage but does not replace timing analysis or hardware fault assessment. The Boolean count describes the size of a test state space, not that every state is reachable or safe in service. Explicitly state relations among occupation, point locking and authority, and demonstrate that hazardous combinations are rejected. Construct interlocking states and refusal conditions for route switching between new tunnel and existing lines. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Conflicting routes and truth-table verification” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：inputs=6 Boolean inputs；計算：combinations=2**inputs=64 states。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: inputs=6 Boolean inputs; calculation: combinations=2**inputs=64 states.","failure":"常見誤解：「聯鎖只要正常路徑通過測試就不需要檢查衝突請求」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Passing normal route tests removes the need to test conflicting requests.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「互斥進路與真值驗證」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Conflicting routes and truth-table verification”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b334-v16-17-k1","title":"互斥進路與真值驗證","titleEn":"Conflicting routes and truth-table verification","text":"聯鎖的核心是明確禁止衝突進路同時成立，安全條件需要由占用、道岔鎖閉和列車完整通過共同決定。狀態數隨布林輸入快速增加，真值表可檢查邏輯完整性，但不能代替時序與硬體故障分析。","textEn":"Interlocking explicitly excludes simultaneous conflicting routes. Occupancy, locked points and complete train passage jointly determine permissive conditions.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-17-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：聯鎖只要正常路徑通過測試就不需要檢查衝突請求 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Passing normal route tests removes the need to test conflicting requests. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"關於「互斥進路與真值驗證」，下列哪一項敘述正確？","questionEn":"Which statement about \"Conflicting routes and truth-table verification\" is correct?","options":["聯鎖只要正常路徑通過測試就不需要檢查衝突請求","兩個定位來源彼此一致就能保證定位沒有共同偏差","聯鎖的核心是明確禁止衝突進路同時成立，安全條件需要由占用、道岔鎖閉和列車完整通過共同決定。"],"optionsEn":["Passing normal route tests removes the need to test conflicting requests.","Agreement between two position sources guarantees absence of common bias.","Interlocking explicitly excludes simultaneous conflicting routes."],"answer":2,"explanation":"聯鎖的核心是明確禁止衝突進路同時成立，安全條件需要由占用、道岔鎖閉和列車完整通過共同決定。 其餘選項是常見誤解。","explanationEn":"Interlocking explicitly excludes simultaneous conflicting routes. The other options are common misconceptions."},"unit":5,"unitFacet":"mechanism","order":1,"sequence":17},{"id":"b334-v16-18","title":"互斥進路與真值驗證：定量估算","titleEn":"Conflicting routes and truth-table verification: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-17"],"objective":"以數值模型估算「互斥進路與真值驗證」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Conflicting routes and truth-table verification” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：inputs=6 Boolean inputs；計算：combinations=2**inputs=64 states。敏感度：inputs 增加 1 個布林輸入至 7 Boolean inputs，其餘固定，結果為 128 states。模型邊界：有限個獨立二值輸入的完整枚舉；不代表實際聯鎖軟體測試已完成。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: inputs=6 Boolean inputs; calculation: combinations=2**inputs=64 states. Sensitivity: inputs, add one Boolean input, to 7 Boolean inputs, with all other inputs fixed, gives 128 states. Model boundary: Complete enumeration of independent binary inputs; not a claim that real interlocking software has been tested. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：把每個允許輸出對應到必要條件，逐項加入反例測試；再檢查占用訊號失效或道岔未鎖閉時是否回到禁止狀態。","observationEn":"How to cross-check: Map every permissive output to its necessary conditions, add counterexample tests, and check that occupancy failure or unlocked points leads to a restrictive state.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b334-v16-18-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：inputs=6 Boolean inputs；計算：combinations=2**inputs=64 states。敏感度：inputs 增加 1 個布林輸入至 7 Boolean inputs，其餘固定，結果為 128 states。模型邊界：有限個獨立二值輸入的完整枚舉；不代表實際聯鎖軟體測試已完成。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: inputs=6 Boolean inputs; calculation: combinations=2**inputs=64 states. Sensitivity: inputs, add one Boolean input, to 7 Boolean inputs, with all other inputs fixed, gives 128 states. Model boundary: Complete enumeration of independent binary inputs; not a claim that real interlocking software has been tested.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-18-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"依「互斥進路與真值驗證」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Conflicting routes and truth-table verification\", which statement holds?","options":["原創假想算例，全部輸入均非本工程操作參數：inputs=6 Boolean inputs。","轉乘路線距離最短就一定適合所有旅客最快銜接","設備可用度高就表示所有安全風險一定很低"],"optionsEn":["Original hypothetical exercise.","The shortest transfer route necessarily gives every passenger the fastest connection.","High equipment availability necessarily means every safety risk is low."],"answer":0,"explanation":"原創假想算例，全部輸入均非本工程操作參數：inputs=6 Boolean inputs；計算：combinations=2**inputs=64 states。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: inputs=6 Boolean inputs; calculation: combinations=2**inputs=64 states. Keep units when recalculating."},"unit":5,"unitFacet":"model","order":2,"sequence":18},{"id":"b334-v16-19","title":"互斥進路與真值驗證：試驗與驗證","titleEn":"Conflicting routes and truth-table verification: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-18"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「互斥進路與真值驗證」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Conflicting routes and truth-table verification” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"把每個允許輸出對應到必要條件，逐項加入反例測試；再檢查占用訊號失效或道岔未鎖閉時是否回到禁止狀態。 從真值表逐列執行故障注入，記錄預期拒絕與實際輸出，並覆核非法狀態不可授權。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Map every permissive output to its necessary conditions, add counterexample tests, and check that occupancy failure or unlocked points leads to a restrictive state. Execute fault injection row by row from the truth table, recording expected refusal and actual output, and verify that illegal states receive no authority. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：為兩條衝突進路建立真值表，標記禁止組合，再加入先占用後解鎖的事件序列，說明組合邏輯和時序邏輯的差異。 再以本單元 inputs 的對照值重算 combinations，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Build a truth table for two conflicting routes, mark forbidden combinations, then add occupancy and release event sequences to distinguish combinational from temporal logic. Also recalculate combinations for the alternative inputs value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：只測正常進路順序會漏掉同時請求和殘留狀態；感測器卡在允許值也可能使紙上正確的邏輯收到錯誤輸入。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Testing only the normal route sequence misses simultaneous requests and residual states; a sensor stuck permissive can feed wrong inputs to otherwise correct logic. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b334-v16-19-k1","title":"驗證方法","titleEn":"Verification method","text":"把每個允許輸出對應到必要條件，逐項加入反例測試；再檢查占用訊號失效或道岔未鎖閉時是否回到禁止狀態。 從真值表逐列執行故障注入，記錄預期拒絕與實際輸出，並覆核非法狀態不可授權。","textEn":"Map every permissive output to its necessary conditions, add counterexample tests, and check that occupancy failure or unlocked points leads to a restrictive state. Execute fault injection row by row from the truth table, recording expected refusal and actual output, and verify that illegal states receive no authority.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-19-k2","title":"現場實務","titleEn":"Site practice","text":"為兩條衝突進路建立真值表，標記禁止組合，再加入先占用後解鎖的事件序列，說明組合邏輯和時序邏輯的差異。 再以本單元 inputs 的對照值重算 combinations，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Build a truth table for two conflicting routes, mark forbidden combinations, then add occupancy and release event sequences to distinguish combinational from temporal logic. Also recalculate combinations for the alternative inputs value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"要驗證「互斥進路與真值驗證」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Conflicting routes and truth-table verification\"?","options":["允收準則可以等看到量測數據後再決定。","把每個允許輸出對應到必要條件，逐項加入反例測試；再檢查占用訊號失效或道岔未鎖閉時是否回到禁止狀態。","兩台儀器量得同樣座標就證明座標絕對正確"],"optionsEn":["Acceptance criteria can be decided after the measured data have been seen.","Map every permissive output to its necessary conditions, add counterexample tests, and check that occupancy failure or unlocked points leads to a restrictive state.","Matching coordinates from two instruments prove absolute coordinate accuracy."],"answer":1,"explanation":"把每個允許輸出對應到必要條件，逐項加入反例測試；再檢查占用訊號失效或道岔未鎖閉時是否回到禁止狀態。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Map every permissive output to its necessary conditions, add counterexample tests, and check that occupancy failure or unlocked points leads to a restrictive state. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":5,"unitFacet":"verification","order":3,"sequence":19},{"id":"b334-v16-20","title":"互斥進路與真值驗證：失效診斷","titleEn":"Conflicting routes and truth-table verification: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-19"],"objective":"從症狀倒推「互斥進路與真值驗證」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Conflicting routes and truth-table verification” and propose discriminating checks, corrective actions and prevention.","instruction":"只測正常進路順序會漏掉同時請求和殘留狀態；感測器卡在允許值也可能使紙上正確的邏輯收到錯誤輸入。 狀態覆蓋率高仍可能缺少危險轉移，須查事件先後。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Testing only the normal route sequence misses simultaneous requests and residual states; a sensor stuck permissive can feed wrong inputs to otherwise correct logic. High state coverage can still miss a hazardous transition; inspect event ordering as well. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：對新隧道與既有線進路切換建立互鎖狀態和拒絕條件。","observationEn":"Link to the mechanism: Construct interlocking states and refusal conditions for route switching between new tunnel and existing lines.","failure":"誤判風險：若相信「聯鎖只要正常路徑通過測試就不需要檢查衝突請求」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Passing normal route tests removes the need to test conflicting requests.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b334-v16-20-k1","title":"失效模式","titleEn":"Failure mode","text":"只測正常進路順序會漏掉同時請求和殘留狀態；感測器卡在允許值也可能使紙上正確的邏輯收到錯誤輸入。 狀態覆蓋率高仍可能缺少危險轉移，須查事件先後。","textEn":"Testing only the normal route sequence misses simultaneous requests and residual states; a sensor stuck permissive can feed wrong inputs to otherwise correct logic. High state coverage can still miss a hazardous transition; inspect event ordering as well.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-20-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"在「互斥進路與真值驗證」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Conflicting routes and truth-table verification\" shows distress, which diagnosis is most reasonable?","options":["症狀相同就代表原因相同，不必用量測區分。","兩個定位來源彼此一致就能保證定位沒有共同偏差","只測正常進路順序會漏掉同時請求和殘留狀態；感測器卡在允許值也可能使紙上正確的邏輯收到錯誤輸入。"],"optionsEn":["Identical symptoms always mean identical causes, so no discriminating measurement is needed.","Agreement between two position sources guarantees absence of common bias.","Testing only the normal route sequence misses simultaneous requests and residual states."],"answer":2,"explanation":"只測正常進路順序會漏掉同時請求和殘留狀態；感測器卡在允許值也可能使紙上正確的邏輯收到錯誤輸入。 需以量測區分可能原因。","explanationEn":"Testing only the normal route sequence misses simultaneous requests and residual states; a sensor stuck permissive can feed wrong inputs to otherwise correct logic. Discriminate candidate causes by measurement."},"unit":5,"unitFacet":"failure","order":4,"sequence":20},{"id":"b334-v16-21","title":"里程融合與不確定度：機制與系統路徑","titleEn":"Position fusion and uncertainty: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-20"],"objective":"說明「里程融合與不確定度」如何影響墨爾本地鐵隧道計畫的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Position fusion and uncertainty” governs forces, deformation, flow or signals in “Melbourne Metro Tunnel project”, and map the relevant inputs, transfer paths and boundaries.","instruction":"獨立位置感測器可用變異數倒數加權，但只有誤差不相關且偏差已校正時，融合後不確定度才按公式下降。輪徑誤差和共同地圖偏差可能讓多個通道一起偏移，不能靠增加感測器數量消除。 兩個獨立無偏估計的資訊量可以相加，較小變異數應獲較大權重。共同偏差不會被這種融合消除，相關性也會破壞公式；較小標準差只能表示宣告模型下的精密度。 在資料更新前後檢查列車位置參考和版本一致性。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「里程融合與不確定度」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Independent position measurements can be weighted by inverse variance, but uncertainty decreases as predicted only when errors are uncorrelated and biases have been corrected. Wheel-diameter error and shared map bias can shift multiple channels together, so merely adding sensors does not remove systematic error. Information from two independent unbiased estimates can be combined, assigning greater weight to smaller variance. Shared bias is not removed by this fusion, and correlation invalidates the expression. Smaller standard deviation represents precision only under the declared statistical model. Check train-position references and version consistency before and after data updates. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Position fusion and uncertainty” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：s1=4.2 m; s2=2 m；計算：sigma=(1/(1/s1**2+1/s2**2))**0.5=1.805721 m。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: s1=4.2 m; s2=2 m; calculation: sigma=(1/(1/s1**2+1/s2**2))**0.5=1.805721 m.","failure":"常見誤解：「兩個定位來源彼此一致就能保證定位沒有共同偏差」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Agreement between two position sources guarantees absence of common bias.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「里程融合與不確定度」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Position fusion and uncertainty”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b334-v16-21-k1","title":"里程融合與不確定度","titleEn":"Position fusion and uncertainty","text":"獨立位置感測器可用變異數倒數加權，但只有誤差不相關且偏差已校正時，融合後不確定度才按公式下降。輪徑誤差和共同地圖偏差可能讓多個通道一起偏移，不能靠增加感測器數量消除。","textEn":"Independent position measurements can be weighted by inverse variance, but uncertainty decreases as predicted only when errors are uncorrelated and biases have been corrected. Wheel-diameter error and shared map bias can shift multiple channels together, so merely adding sensors does not remove systematic error.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-21-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：兩個定位來源彼此一致就能保證定位沒有共同偏差 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Agreement between two position sources guarantees absence of common bias. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"關於「里程融合與不確定度」，下列哪一項敘述正確？","questionEn":"Which statement about \"Position fusion and uncertainty\" is correct?","options":["獨立位置感測器可用變異數倒數加權，但只有誤差不相關且偏差已校正時，融合後不確定度才按公式下降。","兩個定位來源彼此一致就能保證定位沒有共同偏差","降低目標速度時可忽略初速與目標速度的平方差"],"optionsEn":["Independent position measurements can be weighted by inverse variance, but uncertainty decreases as predicted only when errors are uncorrelated and biases have been corrected.","Agreement between two position sources guarantees absence of common bias.","Reducing target speed allows the squared-speed difference to be ignored."],"answer":0,"explanation":"獨立位置感測器可用變異數倒數加權，但只有誤差不相關且偏差已校正時，融合後不確定度才按公式下降。 其餘選項是常見誤解。","explanationEn":"Independent position measurements can be weighted by inverse variance, but uncertainty decreases as predicted only when errors are uncorrelated and biases have been corrected. The other options are common misconceptions."},"unit":6,"unitFacet":"mechanism","order":5,"sequence":21},{"id":"b334-v16-22","title":"里程融合與不確定度：定量估算","titleEn":"Position fusion and uncertainty: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-21"],"objective":"以數值模型估算「里程融合與不確定度」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Position fusion and uncertainty” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：s1=4.2 m; s2=2 m；計算：sigma=(1/(1/s1**2+1/s2**2))**0.5=1.805721 m。敏感度：s1 單獨增加百分之十至 4.62 m，其餘固定，結果為 1.835401 m。模型邊界：零均值獨立高斯誤差；不含共同偏差與完整性風險。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: s1=4.2 m; s2=2 m; calculation: sigma=(1/(1/s1**2+1/s2**2))**0.5=1.805721 m. Sensitivity: s1, increase this input alone by ten percent, to 4.62 m, with all other inputs fixed, gives 1.835401 m. Model boundary: Independent zero-mean Gaussian errors; common bias and integrity risk are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：以獨立已知控制點比較融合前後殘差，逐段檢查偏差及相關性，並故意遮蔽一個感測器觀察降級行為。","observationEn":"How to cross-check: Compare pre-fusion and post-fusion residuals at independently surveyed points, check bias and correlation by segment, and mask one sensor to inspect degraded operation.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b334-v16-22-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：s1=4.2 m; s2=2 m；計算：sigma=(1/(1/s1**2+1/s2**2))**0.5=1.805721 m。敏感度：s1 單獨增加百分之十至 4.62 m，其餘固定，結果為 1.835401 m。模型邊界：零均值獨立高斯誤差；不含共同偏差與完整性風險。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: s1=4.2 m; s2=2 m; calculation: sigma=(1/(1/s1**2+1/s2**2))**0.5=1.805721 m. Sensitivity: s1, increase this input alone by ten percent, to 4.62 m, with all other inputs fixed, gives 1.835401 m. Model boundary: Independent zero-mean Gaussian errors; common bias and integrity risk are excluded.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-22-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"依「里程融合與不確定度」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Position fusion and uncertainty\", which statement holds?","options":["風機已經啟動就能證明隧道每一處濃度同樣下降","原創假想算例，全部輸入均非本工程操作參數：s1=4.2 m; s2=2 m。","施工窗口全長都可以直接乘以施工速度當成可完成量"],"optionsEn":["A running fan proves concentration falls equally at every point in the tunnel.","Original hypothetical exercise.","The entire possession duration can be multiplied by work rate to obtain achievable production."],"answer":1,"explanation":"原創假想算例，全部輸入均非本工程操作參數：s1=4.2 m; s2=2 m；計算：sigma=(1/(1/s1**2+1/s2**2))**0.5=1.805721 m。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: s1=4.2 m; s2=2 m; calculation: sigma=(1/(1/s1**2+1/s2**2))**0.5=1.805721 m. Keep units when recalculating."},"unit":6,"unitFacet":"model","order":6,"sequence":22},{"id":"b334-v16-23","title":"里程融合與不確定度：試驗與驗證","titleEn":"Position fusion and uncertainty: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-22"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「里程融合與不確定度」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Position fusion and uncertainty” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"以獨立已知控制點比較融合前後殘差，逐段檢查偏差及相關性，並故意遮蔽一個感測器觀察降級行為。 以外部參考位置核對兩感測器殘差，檢查平均偏差及相關係數，再比較融合後覆蓋範圍。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Compare pre-fusion and post-fusion residuals at independently surveyed points, check bias and correlation by segment, and mask one sensor to inspect degraded operation. Check both sensor residuals against an external position reference, examine mean bias and correlation, and compare coverage after fusion. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：建立獨立誤差與共同偏差兩組資料，對比融合結果，指出哪一種誤差需要外部控制點才能發現。 再以本單元 s1 的對照值重算 sigma，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Construct independent-error and common-bias datasets, compare their fused results, and identify the error requiring an external control point for detection. Also recalculate sigma for the alternative s1 value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：共用錯誤地圖會讓兩個感測器看似一致卻都錯；錯把相關訊號當獨立會使報告的置信區間過窄。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A shared wrong map can make two sensors agree while both are wrong; treating correlated signals as independent produces an overconfident interval. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b334-v16-23-k1","title":"驗證方法","titleEn":"Verification method","text":"以獨立已知控制點比較融合前後殘差，逐段檢查偏差及相關性，並故意遮蔽一個感測器觀察降級行為。 以外部參考位置核對兩感測器殘差，檢查平均偏差及相關係數，再比較融合後覆蓋範圍。","textEn":"Compare pre-fusion and post-fusion residuals at independently surveyed points, check bias and correlation by segment, and mask one sensor to inspect degraded operation. Check both sensor residuals against an external position reference, examine mean bias and correlation, and compare coverage after fusion.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-23-k2","title":"現場實務","titleEn":"Site practice","text":"建立獨立誤差與共同偏差兩組資料，對比融合結果，指出哪一種誤差需要外部控制點才能發現。 再以本單元 s1 的對照值重算 sigma，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Construct independent-error and common-bias datasets, compare their fused results, and identify the error requiring an external control point for detection. Also recalculate sigma for the alternative s1 value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"要驗證「里程融合與不確定度」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Position fusion and uncertainty\"?","options":["只要結構分析模型看起來合理，就可以省略現場量測與試驗。","兩端高程相同就能證明兩點之間沒有差異沉陷","以獨立已知控制點比較融合前後殘差，逐段檢查偏差及相關性，並故意遮蔽一個感測器觀察降級行為。"],"optionsEn":["If the structural model looks reasonable, site measurement and testing can be skipped.","Equal endpoint elevations prove there is no differential settlement between them.","Compare pre-fusion and post-fusion residuals at independently surveyed points, check bias and correlation by segment, and mask one sensor to inspect degraded operation."],"answer":2,"explanation":"以獨立已知控制點比較融合前後殘差，逐段檢查偏差及相關性，並故意遮蔽一個感測器觀察降級行為。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Compare pre-fusion and post-fusion residuals at independently surveyed points, check bias and correlation by segment, and mask one sensor to inspect degraded operation. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":6,"unitFacet":"verification","order":7,"sequence":23},{"id":"b334-v16-24","title":"里程融合與不確定度：失效診斷","titleEn":"Position fusion and uncertainty: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-23"],"objective":"從症狀倒推「里程融合與不確定度」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Position fusion and uncertainty” and propose discriminating checks, corrective actions and prevention.","instruction":"共用錯誤地圖會讓兩個感測器看似一致卻都錯；錯把相關訊號當獨立會使報告的置信區間過窄。 若兩感測器共用錯誤基準，融合後仍會保持共同偏差。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"A shared wrong map can make two sensors agree while both are wrong; treating correlated signals as independent produces an overconfident interval. If both sensors share a wrong reference, the fused result retains the common bias. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：在資料更新前後檢查列車位置參考和版本一致性。","observationEn":"Link to the mechanism: Check train-position references and version consistency before and after data updates.","failure":"誤判風險：若相信「兩個定位來源彼此一致就能保證定位沒有共同偏差」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Agreement between two position sources guarantees absence of common bias.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b334-v16-24-k1","title":"失效模式","titleEn":"Failure mode","text":"共用錯誤地圖會讓兩個感測器看似一致卻都錯；錯把相關訊號當獨立會使報告的置信區間過窄。 若兩感測器共用錯誤基準，融合後仍會保持共同偏差。","textEn":"A shared wrong map can make two sensors agree while both are wrong; treating correlated signals as independent produces an overconfident interval. If both sensors share a wrong reference, the fused result retains the common bias.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-24-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"在「里程融合與不確定度」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Position fusion and uncertainty\" shows distress, which diagnosis is most reasonable?","options":["共用錯誤地圖會讓兩個感測器看似一致卻都錯；錯把相關訊號當獨立會使報告的置信區間過窄。","只要結構還沒倒，就代表安全餘裕仍然足夠。","降低目標速度時可忽略初速與目標速度的平方差"],"optionsEn":["A shared wrong map can make two sensors agree while both are wrong; treating correlated signals as independent produces an overconfident interval.","As long as the structure is still standing, its safety margin must still be adequate.","Reducing target speed allows the squared-speed difference to be ignored."],"answer":0,"explanation":"共用錯誤地圖會讓兩個感測器看似一致卻都錯；錯把相關訊號當獨立會使報告的置信區間過窄。 需以量測區分可能原因。","explanationEn":"A shared wrong map can make two sensors agree while both are wrong; treating correlated signals as independent produces an overconfident interval. Discriminate candidate causes by measurement."},"unit":6,"unitFacet":"failure","order":8,"sequence":24}],"order":3},{"id":"b334-v16-s4","title":"速度限制轉換與預告距離與轉乘步行與銜接餘裕","titleEn":"Speed-limit transition and warning distance & Transfer walking and connection margin","description":"本階段聚焦「速度限制轉換與預告距離」與「轉乘步行與銜接餘裕」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Speed-limit transition and warning distance\" and \"Transfer walking and connection margin\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b334-v16-25","title":"速度限制轉換與預告距離：機制與系統路徑","titleEn":"Speed-limit transition and warning distance: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-24"],"objective":"說明「速度限制轉換與預告距離」如何影響墨爾本地鐵隧道計畫的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Speed-limit transition and warning distance” governs forces, deformation, flow or signals in “Melbourne Metro Tunnel project”, and map the relevant inputs, transfer paths and boundaries.","instruction":"進入較低速區前需把速度差轉成足夠的減速距離，能量式包含初速與目標速度的平方差。此處用明示減速度得到教學距離，真正保護曲線還需加入定位誤差、坡度、制動建立及車輛差異。 目標速度不一定是零，進入較低速區也需要保護距離。計算使用同一距離基準與速度單位，並把定位誤差和延遲裕度分開，才能避免重複或漏加安全邊界。 將接續區段的目標速度和定位誤差帶入保護距離。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「速度限制轉換與預告距離」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"Before entering a lower-speed section, the train needs distance to remove the difference in kinetic energy. The expression contains the difference of squared initial and target speeds. A teaching deceleration gives one distance; a real protection curve additionally needs position uncertainty, gradient, brake build-up and vehicle variation. The target speed need not be zero: entry into a lower-speed section also requires protection distance. Use one distance reference and consistent speed units. Keep localisation uncertainty and delay margins separate to prevent duplicated or omitted boundaries. Include target speed and localisation uncertainty in protective distance at the connecting section. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Speed-limit transition and warning distance” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：initial=25.2 m/s; target=10 m/s; a=0.65 m/s^2；計算：transition=(initial**2-target**2)/(2*a)=411.5692 m。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: initial=25.2 m/s; target=10 m/s; a=0.65 m/s^2; calculation: transition=(initial**2-target**2)/(2*a)=411.5692 m.","failure":"常見誤解：「降低目標速度時可忽略初速與目標速度的平方差」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"Reducing target speed allows the squared-speed difference to be ignored.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「速度限制轉換與預告距離」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Speed-limit transition and warning distance”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b334-v16-25-k1","title":"速度限制轉換與預告距離","titleEn":"Speed-limit transition and warning distance","text":"進入較低速區前需把速度差轉成足夠的減速距離，能量式包含初速與目標速度的平方差。此處用明示減速度得到教學距離，真正保護曲線還需加入定位誤差、坡度、制動建立及車輛差異。","textEn":"Before entering a lower-speed section, the train needs distance to remove the difference in kinetic energy. The expression contains the difference of squared initial and target speeds.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-25-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：降低目標速度時可忽略初速與目標速度的平方差 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: Reducing target speed allows the squared-speed difference to be ignored. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"關於「速度限制轉換與預告距離」，下列哪一項敘述正確？","questionEn":"Which statement about \"Speed-limit transition and warning distance\" is correct?","options":["降低目標速度時可忽略初速與目標速度的平方差","進入較低速區前需把速度差轉成足夠的減速距離，能量式包含初速與目標速度的平方差。","轉乘路線距離最短就一定適合所有旅客最快銜接"],"optionsEn":["Reducing target speed allows the squared-speed difference to be ignored.","Before entering a lower-speed section, the train needs distance to remove the difference in kinetic energy.","The shortest transfer route necessarily gives every passenger the fastest connection."],"answer":1,"explanation":"進入較低速區前需把速度差轉成足夠的減速距離，能量式包含初速與目標速度的平方差。 其餘選項是常見誤解。","explanationEn":"Before entering a lower-speed section, the train needs distance to remove the difference in kinetic energy. The other options are common misconceptions."},"unit":7,"unitFacet":"mechanism","order":1,"sequence":25},{"id":"b334-v16-26","title":"速度限制轉換與預告距離：定量估算","titleEn":"Speed-limit transition and warning distance: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-25"],"objective":"以數值模型估算「速度限制轉換與預告距離」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Speed-limit transition and warning distance” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：initial=25.2 m/s; target=10 m/s; a=0.65 m/s^2；計算：transition=(initial**2-target**2)/(2*a)=411.5692 m。敏感度：initial 單獨增加百分之十至 27.72 m/s，其餘固定，結果為 514.1526 m。模型邊界：初速大於目標速度且定減速度；沒有通訊延遲與安全裕度。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: initial=25.2 m/s; target=10 m/s; a=0.65 m/s^2; calculation: transition=(initial**2-target**2)/(2*a)=411.5692 m. Sensitivity: initial, increase this input alone by ten percent, to 27.72 m/s, with all other inputs fixed, gives 514.1526 m. Model boundary: Initial speed above target and constant deceleration; communication delay and safety margins are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：重播速度剖面並檢查每個限制點的里程基準，將定位誤差和煞車建立時間分別加入，不以單次成功停準代替整個包絡驗證。","observationEn":"How to cross-check: Replay speed profiles with a common distance datum, add positioning error and brake build-up separately, and do not substitute one successful stop for verification of the full envelope.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b334-v16-26-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：initial=25.2 m/s; target=10 m/s; a=0.65 m/s^2；計算：transition=(initial**2-target**2)/(2*a)=411.5692 m。敏感度：initial 單獨增加百分之十至 27.72 m/s，其餘固定，結果為 514.1526 m。模型邊界：初速大於目標速度且定減速度；沒有通訊延遲與安全裕度。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: initial=25.2 m/s; target=10 m/s; a=0.65 m/s^2; calculation: transition=(initial**2-target**2)/(2*a)=411.5692 m. Sensitivity: initial, increase this input alone by ten percent, to 27.72 m/s, with all other inputs fixed, gives 514.1526 m. Model boundary: Initial speed above target and constant deceleration; communication delay and safety margins are excluded.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-26-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"依「速度限制轉換與預告距離」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Speed-limit transition and warning distance\", which statement holds?","options":["設備可用度高就表示所有安全風險一定很低","兩台儀器量得同樣座標就證明座標絕對正確","原創假想算例，全部輸入均非本工程操作參數：initial=25.2 m/s; target=10 m/s; a=0.65 m/s^2。"],"optionsEn":["High equipment availability necessarily means every safety risk is low.","Matching coordinates from two instruments prove absolute coordinate accuracy.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：initial=25.2 m/s; target=10 m/s; a=0.65 m/s^2；計算：transition=(initial**2-target**2)/(2*a)=411.5692 m。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: initial=25.2 m/s; target=10 m/s; a=0.65 m/s^2; calculation: transition=(initial**2-target**2)/(2*a)=411.5692 m. Keep units when recalculating."},"unit":7,"unitFacet":"model","order":2,"sequence":26},{"id":"b334-v16-27","title":"速度限制轉換與預告距離：試驗與驗證","titleEn":"Speed-limit transition and warning distance: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-26"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「速度限制轉換與預告距離」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Speed-limit transition and warning distance” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"重播速度剖面並檢查每個限制點的里程基準，將定位誤差和煞車建立時間分別加入，不以單次成功停準代替整個包絡驗證。 以已知初速與目標速度重播控制資料，核對速度單位、里程方向及列車前端參考位置。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Replay speed profiles with a common distance datum, add positioning error and brake build-up separately, and do not substitute one successful stop for verification of the full envelope. Replay control data at known initial and target speeds, checking speed units, chainage direction and the reference position of the train front. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：對同一初速設定兩個目標速度，重算轉換距離，畫出能量差並說明為何不能按速度差線性縮放距離。 再以本單元 initial 的對照值重算 transition，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Use two target speeds at one initial speed, recalculate transition distance, plot the energy differences, and explain why distance cannot scale linearly with the speed difference. Also recalculate transition for the alternative initial value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：限制點座標偏移或單位錯誤會使制動開始過晚；過度依賴平均減速度則可能漏掉低黏著條件下的長制動距離。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: A shifted restriction coordinate or unit error causes late braking, while reliance on mean deceleration can miss long stopping distances under low adhesion. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b334-v16-27-k1","title":"驗證方法","titleEn":"Verification method","text":"重播速度剖面並檢查每個限制點的里程基準，將定位誤差和煞車建立時間分別加入，不以單次成功停準代替整個包絡驗證。 以已知初速與目標速度重播控制資料，核對速度單位、里程方向及列車前端參考位置。","textEn":"Replay speed profiles with a common distance datum, add positioning error and brake build-up separately, and do not substitute one successful stop for verification of the full envelope. Replay control data at known initial and target speeds, checking speed units, chainage direction and the reference position of the train front.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-27-k2","title":"現場實務","titleEn":"Site practice","text":"對同一初速設定兩個目標速度，重算轉換距離，畫出能量差並說明為何不能按速度差線性縮放距離。 再以本單元 initial 的對照值重算 transition，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Use two target speeds at one initial speed, recalculate transition distance, plot the energy differences, and explain why distance cannot scale linearly with the speed difference. Also recalculate transition for the alternative initial value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"要驗證「速度限制轉換與預告距離」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Speed-limit transition and warning distance\"?","options":["重播速度剖面並檢查每個限制點的里程基準，將定位誤差和煞車建立時間分別加入，不以單次成功停準代替整個包絡驗證。","量測時不必記錄溫度、速度、運行歷程與施工荷重，因為它們不會影響結果。","注入漿量超過幾何空隙體積就能證明沒有殘留空洞"],"optionsEn":["Replay speed profiles with a common distance datum, add positioning error and brake build-up separately, and do not substitute one successful stop for verification of the full envelope.","Temperature, speed, operating history and construction loads need not be recorded because they cannot affect the result.","Injecting more than the geometric void volume proves that no void remains."],"answer":0,"explanation":"重播速度剖面並檢查每個限制點的里程基準，將定位誤差和煞車建立時間分別加入，不以單次成功停準代替整個包絡驗證。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Replay speed profiles with a common distance datum, add positioning error and brake build-up separately, and do not substitute one successful stop for verification of the full envelope. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":7,"unitFacet":"verification","order":3,"sequence":27},{"id":"b334-v16-28","title":"速度限制轉換與預告距離：失效診斷","titleEn":"Speed-limit transition and warning distance: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-27"],"objective":"從症狀倒推「速度限制轉換與預告距離」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Speed-limit transition and warning distance” and propose discriminating checks, corrective actions and prevention.","instruction":"限制點座標偏移或單位錯誤會使制動開始過晚；過度依賴平均減速度則可能漏掉低黏著條件下的長制動距離。 若目標速度高於初速，此減速模型的工況設定便不成立。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"A shifted restriction coordinate or unit error causes late braking, while reliance on mean deceleration can miss long stopping distances under low adhesion. If target speed exceeds initial speed, the stated deceleration case no longer applies. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：將接續區段的目標速度和定位誤差帶入保護距離。","observationEn":"Link to the mechanism: Include target speed and localisation uncertainty in protective distance at the connecting section.","failure":"誤判風險：若相信「降低目標速度時可忽略初速與目標速度的平方差」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"Reducing target speed allows the squared-speed difference to be ignored.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b334-v16-28-k1","title":"失效模式","titleEn":"Failure mode","text":"限制點座標偏移或單位錯誤會使制動開始過晚；過度依賴平均減速度則可能漏掉低黏著條件下的長制動距離。 若目標速度高於初速，此減速模型的工況設定便不成立。","textEn":"A shifted restriction coordinate or unit error causes late braking, while reliance on mean deceleration can miss long stopping distances under low adhesion. If target speed exceeds initial speed, the stated deceleration case no longer applies.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-28-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"在「速度限制轉換與預告距離」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Speed-limit transition and warning distance\" shows distress, which diagnosis is most reasonable?","options":["所有異常都來自施工人員失誤，設計與細部不需要檢討。","限制點座標偏移或單位錯誤會使制動開始過晚；過度依賴平均減速度則可能漏掉低黏著條件下的長制動距離。","轉乘路線距離最短就一定適合所有旅客最快銜接"],"optionsEn":["Every anomaly is a workmanship error, so design and detailing never need review.","A shifted restriction coordinate or unit error causes late braking, while reliance on mean deceleration can miss long stopping distances under low adhesion.","The shortest transfer route necessarily gives every passenger the fastest connection."],"answer":1,"explanation":"限制點座標偏移或單位錯誤會使制動開始過晚；過度依賴平均減速度則可能漏掉低黏著條件下的長制動距離。 需以量測區分可能原因。","explanationEn":"A shifted restriction coordinate or unit error causes late braking, while reliance on mean deceleration can miss long stopping distances under low adhesion. Discriminate candidate causes by measurement."},"unit":7,"unitFacet":"failure","order":4,"sequence":28},{"id":"b334-v16-29","title":"轉乘步行與銜接餘裕：機制與系統路徑","titleEn":"Transfer walking and connection margin: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-28"],"objective":"說明「轉乘步行與銜接餘裕」如何影響墨爾本地鐵隧道計畫的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Transfer walking and connection margin” governs forces, deformation, flow or signals in “Melbourne Metro Tunnel project”, and map the relevant inputs, transfer paths and boundaries.","instruction":"轉乘能否銜接取決於實際可用時間扣除下車、步行、垂直動線與候車需求。最短路徑不一定最快，因為樓梯、閘門與人流交會造成等待；無障礙路徑需要獨立列出而非套用同一速度。 距離除速度只表示行走或移動時間，等待列車、排隊和辨識路徑應另列。使用單一平均速度會掩蓋行李、行動能力和雙向干擾，應以分段分群資料檢查。 比較新站開放前後的旅客步行與垂直轉乘路徑。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「轉乘步行與銜接餘裕」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A connection depends on available time after alighting, walking, vertical circulation and boarding needs. The shortest route is not always fastest because stairs, gates and crossing streams cause waiting. Accessible routes need their own timing rather than an assumed common walking speed. Distance divided by speed represents movement only; train waiting, queueing and wayfinding need separate terms. One mean speed hides baggage, mobility differences and opposing flow. Check the result with segmented measurements for relevant passenger groups. Compare walking and vertical-transfer paths before and after the new stations open. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Transfer walking and connection margin” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：available=300 s; distance=189 m; speed=1 m/s; vertical=45 s；計算：margin=available-distance/speed-vertical=66 s。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: available=300 s; distance=189 m; speed=1 m/s; vertical=45 s; calculation: margin=available-distance/speed-vertical=66 s.","failure":"常見誤解：「轉乘路線距離最短就一定適合所有旅客最快銜接」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"The shortest transfer route necessarily gives every passenger the fastest connection.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「轉乘步行與銜接餘裕」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Transfer walking and connection margin”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b334-v16-29-k1","title":"轉乘步行與銜接餘裕","titleEn":"Transfer walking and connection margin","text":"轉乘能否銜接取決於實際可用時間扣除下車、步行、垂直動線與候車需求。最短路徑不一定最快，因為樓梯、閘門與人流交會造成等待；無障礙路徑需要獨立列出而非套用同一速度。","textEn":"A connection depends on available time after alighting, walking, vertical circulation and boarding needs. The shortest route is not always fastest because stairs, gates and crossing streams cause waiting.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-29-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：轉乘路線距離最短就一定適合所有旅客最快銜接 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: The shortest transfer route necessarily gives every passenger the fastest connection. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"關於「轉乘步行與銜接餘裕」，下列哪一項敘述正確？","questionEn":"Which statement about \"Transfer walking and connection margin\" is correct?","options":["轉乘路線距離最短就一定適合所有旅客最快銜接","風機已經啟動就能證明隧道每一處濃度同樣下降","轉乘能否銜接取決於實際可用時間扣除下車、步行、垂直動線與候車需求。"],"optionsEn":["The shortest transfer route necessarily gives every passenger the fastest connection.","A running fan proves concentration falls equally at every point in the tunnel.","A connection depends on available time after alighting, walking, vertical circulation and boarding needs."],"answer":2,"explanation":"轉乘能否銜接取決於實際可用時間扣除下車、步行、垂直動線與候車需求。 其餘選項是常見誤解。","explanationEn":"A connection depends on available time after alighting, walking, vertical circulation and boarding needs. The other options are common misconceptions."},"unit":8,"unitFacet":"mechanism","order":5,"sequence":29},{"id":"b334-v16-30","title":"轉乘步行與銜接餘裕：定量估算","titleEn":"Transfer walking and connection margin: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-29"],"objective":"以數值模型估算「轉乘步行與銜接餘裕」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Transfer walking and connection margin” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：available=300 s; distance=189 m; speed=1 m/s; vertical=45 s；計算：margin=available-distance/speed-vertical=66 s。敏感度：distance 單獨增加百分之十至 207.9 m，其餘固定，結果為 47.1 s。模型邊界：固定步速與額外時間；不包含動態排隊或旅客個別差異分布。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: available=300 s; distance=189 m; speed=1 m/s; vertical=45 s; calculation: margin=available-distance/speed-vertical=66 s. Sensitivity: distance, increase this input alone by ten percent, to 207.9 m, with all other inputs fixed, gives 47.1 s. Model boundary: Fixed walking speed and additional time; dynamic queues and individual variability distributions are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：以匿名實測旅程時間分位數比較路徑，記錄電梯等待及閘門排隊，檢查轉乘圖的距離是否包含所有垂直動線。","observationEn":"How to cross-check: Compare route-time quantiles from anonymous observations, record lift and gate waits, and check that route distances include every vertical circulation segment.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b334-v16-30-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：available=300 s; distance=189 m; speed=1 m/s; vertical=45 s；計算：margin=available-distance/speed-vertical=66 s。敏感度：distance 單獨增加百分之十至 207.9 m，其餘固定，結果為 47.1 s。模型邊界：固定步速與額外時間；不包含動態排隊或旅客個別差異分布。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: available=300 s; distance=189 m; speed=1 m/s; vertical=45 s; calculation: margin=available-distance/speed-vertical=66 s. Sensitivity: distance, increase this input alone by ten percent, to 207.9 m, with all other inputs fixed, gives 47.1 s. Model boundary: Fixed walking speed and additional time; dynamic queues and individual variability distributions are excluded.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-30-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"依「轉乘步行與銜接餘裕」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Transfer walking and connection margin\", which statement holds?","options":["原創假想算例，全部輸入均非本工程操作參數：available=300 s; distance=189 m; speed=1 m/s; vertical=45 s。","施工窗口全長都可以直接乘以施工速度當成可完成量","兩端高程相同就能證明兩點之間沒有差異沉陷"],"optionsEn":["Original hypothetical exercise.","The entire possession duration can be multiplied by work rate to obtain achievable production.","Equal endpoint elevations prove there is no differential settlement between them."],"answer":0,"explanation":"原創假想算例，全部輸入均非本工程操作參數：available=300 s; distance=189 m; speed=1 m/s; vertical=45 s；計算：margin=available-distance/speed-vertical=66 s。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: available=300 s; distance=189 m; speed=1 m/s; vertical=45 s; calculation: margin=available-distance/speed-vertical=66 s. Keep units when recalculating."},"unit":8,"unitFacet":"model","order":6,"sequence":30},{"id":"b334-v16-31","title":"轉乘步行與銜接餘裕：試驗與驗證","titleEn":"Transfer walking and connection margin: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-30"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「轉乘步行與銜接餘裕」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Transfer walking and connection margin” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"以匿名實測旅程時間分位數比較路徑，記錄電梯等待及閘門排隊，檢查轉乘圖的距離是否包含所有垂直動線。 在路徑起終點對時，逐段記錄水平、垂直與等待時間，核對是否漏計驗票或排隊。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Compare route-time quantiles from anonymous observations, record lift and gate waits, and check that route distances include every vertical circulation segment. Synchronise route endpoints, record horizontal movement, vertical movement and waiting separately, and check for omitted gate processing or queues. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：比較一般與無障礙兩條路徑的餘裕，加入一台電梯停機情境，說明時刻表調整與空間導引分別能改善哪一段。 再以本單元 distance 的對照值重算 margin，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Compare connection margins for ordinary and accessible routes, add one unavailable lift, and distinguish improvements from timetable changes versus spatial guidance. Also recalculate margin for the alternative distance value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：只用最快步行者校準會低估多數人的轉乘時間；電梯停機又可能使唯一無障礙路徑失去連續性。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Calibrating to the fastest walkers understates many passengers’ transfer time; a failed lift can also break the only continuous accessible route. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b334-v16-31-k1","title":"驗證方法","titleEn":"Verification method","text":"以匿名實測旅程時間分位數比較路徑，記錄電梯等待及閘門排隊，檢查轉乘圖的距離是否包含所有垂直動線。 在路徑起終點對時，逐段記錄水平、垂直與等待時間，核對是否漏計驗票或排隊。","textEn":"Compare route-time quantiles from anonymous observations, record lift and gate waits, and check that route distances include every vertical circulation segment. Synchronise route endpoints, record horizontal movement, vertical movement and waiting separately, and check for omitted gate processing or queues.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-31-k2","title":"現場實務","titleEn":"Site practice","text":"比較一般與無障礙兩條路徑的餘裕，加入一台電梯停機情境，說明時刻表調整與空間導引分別能改善哪一段。 再以本單元 distance 的對照值重算 margin，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Compare connection margins for ordinary and accessible routes, add one unavailable lift, and distinguish improvements from timetable changes versus spatial guidance. Also recalculate margin for the alternative distance value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"要驗證「轉乘步行與銜接餘裕」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Transfer walking and connection margin\"?","options":["沿用另一處鐵路設施或路線的量測結果，就可視為本工程已完成驗證。","以匿名實測旅程時間分位數比較路徑，記錄電梯等待及閘門排隊，檢查轉乘圖的距離是否包含所有垂直動線。","聯鎖只要正常路徑通過測試就不需要檢查衝突請求"],"optionsEn":["Reusing results from another railway facility or route counts as verifying this structure.","Compare route-time quantiles from anonymous observations, record lift and gate waits, and check that route distances include every vertical circulation segment.","Passing normal route tests removes the need to test conflicting requests."],"answer":1,"explanation":"以匿名實測旅程時間分位數比較路徑，記錄電梯等待及閘門排隊，檢查轉乘圖的距離是否包含所有垂直動線。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Compare route-time quantiles from anonymous observations, record lift and gate waits, and check that route distances include every vertical circulation segment. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":8,"unitFacet":"verification","order":7,"sequence":31},{"id":"b334-v16-32","title":"轉乘步行與銜接餘裕：失效診斷","titleEn":"Transfer walking and connection margin: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-31"],"objective":"從症狀倒推「轉乘步行與銜接餘裕」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Transfer walking and connection margin” and propose discriminating checks, corrective actions and prevention.","instruction":"只用最快步行者校準會低估多數人的轉乘時間；電梯停機又可能使唯一無障礙路徑失去連續性。 旅客走錯路會改變實際距離，需比較引導前後的路徑。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Calibrating to the fastest walkers understates many passengers’ transfer time; a failed lift can also break the only continuous accessible route. Wrong turns change actual distance; compare observed routes before and after guidance changes. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：比較新站開放前後的旅客步行與垂直轉乘路徑。","observationEn":"Link to the mechanism: Compare walking and vertical-transfer paths before and after the new stations open.","failure":"誤判風險：若相信「轉乘路線距離最短就一定適合所有旅客最快銜接」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"The shortest transfer route necessarily gives every passenger the fastest connection.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b334-v16-32-k1","title":"失效模式","titleEn":"Failure mode","text":"只用最快步行者校準會低估多數人的轉乘時間；電梯停機又可能使唯一無障礙路徑失去連續性。 旅客走錯路會改變實際距離，需比較引導前後的路徑。","textEn":"Calibrating to the fastest walkers understates many passengers’ transfer time; a failed lift can also break the only continuous accessible route. Wrong turns change actual distance; compare observed routes before and after guidance changes.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-32-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"在「轉乘步行與銜接餘裕」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Transfer walking and connection margin\" shows distress, which diagnosis is most reasonable?","options":["補一層塗料或放寬允收值，就能解決大多數劣化問題。","風機已經啟動就能證明隧道每一處濃度同樣下降","只用最快步行者校準會低估多數人的轉乘時間；電梯停機又可能使唯一無障礙路徑失去連續性。"],"optionsEn":["Adding a coat of paint or widening the acceptance limits solves most deterioration problems.","A running fan proves concentration falls equally at every point in the tunnel.","Calibrating to the fastest walkers understates many passengers’ transfer time; a failed lift can also break the only continuous accessible route."],"answer":2,"explanation":"只用最快步行者校準會低估多數人的轉乘時間；電梯停機又可能使唯一無障礙路徑失去連續性。 需以量測區分可能原因。","explanationEn":"Calibrating to the fastest walkers understates many passengers’ transfer time; a failed lift can also break the only continuous accessible route. Discriminate candidate causes by measurement."},"unit":8,"unitFacet":"failure","order":8,"sequence":32}],"order":4},{"id":"b334-v16-s5","title":"隧道換氣與稀釋時間與可用度與修復時間","titleEn":"Tunnel air exchange and dilution time & Availability and repair time","description":"本階段聚焦「隧道換氣與稀釋時間」與「可用度與修復時間」：先建立機制、系統路徑與定量模型，再設計試驗驗證並診斷失效。","descriptionEn":"This stage covers \"Tunnel air exchange and dilution time\" and \"Availability and repair time\": establish the mechanism, system paths and quantitative model first, then design verification and diagnose failures.","steps":[{"id":"b334-v16-33","title":"隧道換氣與稀釋時間：機制與系統路徑","titleEn":"Tunnel air exchange and dilution time: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-32"],"objective":"說明「隧道換氣與稀釋時間」如何影響墨爾本地鐵隧道計畫的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Tunnel air exchange and dilution time” governs forces, deformation, flow or signals in “Melbourne Metro Tunnel project”, and map the relevant inputs, transfer paths and boundaries.","instruction":"完全混合空間的濃度在定風量清除下呈指數衰減，體積除以風量給出特徵時間。真實隧道存在分層、死角及列車活塞風，因此這個模型只適合示範稀釋量級，不能直接用作火災避難判定。 完全混合且污染源已停止時，濃度以指數衰減；剩餘比例必須介於零與一。換氣率是流量除以容積，清除時間還依目標濃度而變，不能把一次換氣直接當成全部清除。 分開一般換氣與隧道活塞風的量測邊界，避免重複計量。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「隧道換氣與稀釋時間」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"A perfectly mixed volume under constant clean-air flow exhibits exponential concentration decay, with volume divided by flow as the time constant. Real tunnels contain layering, stagnant regions and train-induced piston flow. This model illustrates dilution scale and cannot establish fire evacuation tenability. For perfect mixing after the source stops, concentration decays exponentially and the remaining fraction lies between zero and one. Air-change rate is flow divided by volume, while clearance time also depends on target concentration. One air change does not mean complete removal. Separate normal-ventilation and piston-airflow measurement boundaries to avoid double counting. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Tunnel air exchange and dilution time” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：volume=3000 m^3; flow=26.25 m^3/s; remaining=0.1 1；計算：dilution_time=-volume/flow*log(remaining)=263.1526 s。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: volume=3000 m^3; flow=26.25 m^3/s; remaining=0.1 1; calculation: dilution_time=-volume/flow*log(remaining)=263.1526 s.","failure":"常見誤解：「風機已經啟動就能證明隧道每一處濃度同樣下降」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"A running fan proves concentration falls equally at every point in the tunnel.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「隧道換氣與稀釋時間」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Tunnel air exchange and dilution time”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b334-v16-33-k1","title":"隧道換氣與稀釋時間","titleEn":"Tunnel air exchange and dilution time","text":"完全混合空間的濃度在定風量清除下呈指數衰減，體積除以風量給出特徵時間。真實隧道存在分層、死角及列車活塞風，因此這個模型只適合示範稀釋量級，不能直接用作火災避難判定。","textEn":"A perfectly mixed volume under constant clean-air flow exhibits exponential concentration decay, with volume divided by flow as the time constant. Real tunnels contain layering, stagnant regions and train-induced piston flow.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-33-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：風機已經啟動就能證明隧道每一處濃度同樣下降 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: A running fan proves concentration falls equally at every point in the tunnel. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"關於「隧道換氣與稀釋時間」，下列哪一項敘述正確？","questionEn":"Which statement about \"Tunnel air exchange and dilution time\" is correct?","options":["完全混合空間的濃度在定風量清除下呈指數衰減，體積除以風量給出特徵時間。","風機已經啟動就能證明隧道每一處濃度同樣下降","設備可用度高就表示所有安全風險一定很低"],"optionsEn":["A perfectly mixed volume under constant clean-air flow exhibits exponential concentration decay, with volume divided by flow as the time constant.","A running fan proves concentration falls equally at every point in the tunnel.","High equipment availability necessarily means every safety risk is low."],"answer":0,"explanation":"完全混合空間的濃度在定風量清除下呈指數衰減，體積除以風量給出特徵時間。 其餘選項是常見誤解。","explanationEn":"A perfectly mixed volume under constant clean-air flow exhibits exponential concentration decay, with volume divided by flow as the time constant. The other options are common misconceptions."},"unit":9,"unitFacet":"mechanism","order":1,"sequence":33},{"id":"b334-v16-34","title":"隧道換氣與稀釋時間：定量估算","titleEn":"Tunnel air exchange and dilution time: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-33"],"objective":"以數值模型估算「隧道換氣與稀釋時間」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Tunnel air exchange and dilution time” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：volume=3000 m^3; flow=26.25 m^3/s; remaining=0.1 1；計算：dilution_time=-volume/flow*log(remaining)=263.1526 s。敏感度：flow 單獨增加百分之十至 28.875 m^3/s，其餘固定，結果為 239.2296 s。模型邊界：完全混合且污染源已停止；不含煙層、熱浮力與火災成長。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: volume=3000 m^3; flow=26.25 m^3/s; remaining=0.1 1; calculation: dilution_time=-volume/flow*log(remaining)=263.1526 s. Sensitivity: flow, increase this input alone by ten percent, to 28.875 m^3/s, with all other inputs fixed, gives 239.2296 s. Model boundary: Perfect mixing after source removal; smoke layers, buoyancy and fire growth are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：用非危險示蹤試驗在不同高度與距離採樣，量測實際風量並檢查濃度衰減是否符合單一指數。","observationEn":"How to cross-check: Use a harmless tracer test with samples at several heights and distances, measure actual airflow, and check whether one exponential describes the decay.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b334-v16-34-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：volume=3000 m^3; flow=26.25 m^3/s; remaining=0.1 1；計算：dilution_time=-volume/flow*log(remaining)=263.1526 s。敏感度：flow 單獨增加百分之十至 28.875 m^3/s，其餘固定，結果為 239.2296 s。模型邊界：完全混合且污染源已停止；不含煙層、熱浮力與火災成長。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: volume=3000 m^3; flow=26.25 m^3/s; remaining=0.1 1; calculation: dilution_time=-volume/flow*log(remaining)=263.1526 s. Sensitivity: flow, increase this input alone by ten percent, to 28.875 m^3/s, with all other inputs fixed, gives 239.2296 s. Model boundary: Perfect mixing after source removal; smoke layers, buoyancy and fire growth are excluded.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-34-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"依「隧道換氣與稀釋時間」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Tunnel air exchange and dilution time\", which statement holds?","options":["兩台儀器量得同樣座標就證明座標絕對正確","原創假想算例，全部輸入均非本工程操作參數：volume=3000 m^3; flow=26.25 m^3/s; remaining=0.1 1。","注入漿量超過幾何空隙體積就能證明沒有殘留空洞"],"optionsEn":["Matching coordinates from two instruments prove absolute coordinate accuracy.","Original hypothetical exercise.","Injecting more than the geometric void volume proves that no void remains."],"answer":1,"explanation":"原創假想算例，全部輸入均非本工程操作參數：volume=3000 m^3; flow=26.25 m^3/s; remaining=0.1 1；計算：dilution_time=-volume/flow*log(remaining)=263.1526 s。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: volume=3000 m^3; flow=26.25 m^3/s; remaining=0.1 1; calculation: dilution_time=-volume/flow*log(remaining)=263.1526 s. Keep units when recalculating."},"unit":9,"unitFacet":"model","order":2,"sequence":34},{"id":"b334-v16-35","title":"隧道換氣與稀釋時間：試驗與驗證","titleEn":"Tunnel air exchange and dilution time: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-34"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「隧道換氣與稀釋時間」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Tunnel air exchange and dilution time” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"用非危險示蹤試驗在不同高度與距離採樣，量測實際風量並檢查濃度衰減是否符合單一指數。 以安全示蹤氣體衰減核對時間常數，多點量測濃度並保留門狀態，檢查是否存在未停止源。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Use a harmless tracer test with samples at several heights and distances, measure actual airflow, and check whether one exponential describes the decay. Check the time constant with safe tracer decay, measure concentration at multiple points, retain door states, and check for a continuing source. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：對兩種風量計算達到同一殘餘比例的時間，加入一個不完全混合死角，說明量測配置如何發現模型失配。 再以本單元 flow 的對照值重算 dilution_time，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Calculate time to one residual fraction at two airflows, add a poorly mixed pocket, and explain how sensor placement can reveal model mismatch. Also recalculate dilution_time for the alternative flow value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：死角可能在平均濃度下降後仍維持高濃度；風機反轉或風門錯位也會改變流路，不能只用風機啟動回饋判斷通風。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Stagnant pockets may remain concentrated after the average falls; reversed fans or misplaced dampers alter flow paths, so a running-status signal alone cannot verify ventilation. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b334-v16-35-k1","title":"驗證方法","titleEn":"Verification method","text":"用非危險示蹤試驗在不同高度與距離採樣，量測實際風量並檢查濃度衰減是否符合單一指數。 以安全示蹤氣體衰減核對時間常數，多點量測濃度並保留門狀態，檢查是否存在未停止源。","textEn":"Use a harmless tracer test with samples at several heights and distances, measure actual airflow, and check whether one exponential describes the decay. Check the time constant with safe tracer decay, measure concentration at multiple points, retain door states, and check for a continuing source.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-35-k2","title":"現場實務","titleEn":"Site practice","text":"對兩種風量計算達到同一殘餘比例的時間，加入一個不完全混合死角，說明量測配置如何發現模型失配。 再以本單元 flow 的對照值重算 dilution_time，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Calculate time to one residual fraction at two airflows, add a poorly mixed pocket, and explain how sensor placement can reveal model mismatch. Also recalculate dilution_time for the alternative flow value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"要驗證「隧道換氣與稀釋時間」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Tunnel air exchange and dilution time\"?","options":["只看一次讀值或外觀即可判定合格，不需要基準點、參考試體或重複量測。","兩個定位來源彼此一致就能保證定位沒有共同偏差","用非危險示蹤試驗在不同高度與距離採樣，量測實際風量並檢查濃度衰減是否符合單一指數。"],"optionsEn":["A single reading or a visual impression is enough to accept the work; no datum, reference specimen or repeat measurement is needed.","Agreement between two position sources guarantees absence of common bias.","Use a harmless tracer test with samples at several heights and distances, measure actual airflow, and check whether one exponential describes the decay."],"answer":2,"explanation":"用非危險示蹤試驗在不同高度與距離採樣，量測實際風量並檢查濃度衰減是否符合單一指數。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Use a harmless tracer test with samples at several heights and distances, measure actual airflow, and check whether one exponential describes the decay. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":9,"unitFacet":"verification","order":3,"sequence":35},{"id":"b334-v16-36","title":"隧道換氣與稀釋時間：失效診斷","titleEn":"Tunnel air exchange and dilution time: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-35"],"objective":"從症狀倒推「隧道換氣與稀釋時間」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Tunnel air exchange and dilution time” and propose discriminating checks, corrective actions and prevention.","instruction":"死角可能在平均濃度下降後仍維持高濃度；風機反轉或風門錯位也會改變流路，不能只用風機啟動回饋判斷通風。 風機有轉不代表有效稀釋，需查風道旁通和持續污染源。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Stagnant pockets may remain concentrated after the average falls; reversed fans or misplaced dampers alter flow paths, so a running-status signal alone cannot verify ventilation. A running fan does not prove effective dilution; inspect bypass and continuing contaminant sources. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：分開一般換氣與隧道活塞風的量測邊界，避免重複計量。","observationEn":"Link to the mechanism: Separate normal-ventilation and piston-airflow measurement boundaries to avoid double counting.","failure":"誤判風險：若相信「風機已經啟動就能證明隧道每一處濃度同樣下降」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"A running fan proves concentration falls equally at every point in the tunnel.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b334-v16-36-k1","title":"失效模式","titleEn":"Failure mode","text":"死角可能在平均濃度下降後仍維持高濃度；風機反轉或風門錯位也會改變流路，不能只用風機啟動回饋判斷通風。 風機有轉不代表有效稀釋，需查風道旁通和持續污染源。","textEn":"Stagnant pockets may remain concentrated after the average falls; reversed fans or misplaced dampers alter flow paths, so a running-status signal alone cannot verify ventilation. A running fan does not prove effective dilution; inspect bypass and continuing contaminant sources.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-36-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"在「隧道換氣與稀釋時間」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Tunnel air exchange and dilution time\" shows distress, which diagnosis is most reasonable?","options":["死角可能在平均濃度下降後仍維持高濃度；風機反轉或風門錯位也會改變流路，不能只用風機啟動回饋判斷通風。","裂縫或異常只出現一次就可以忽略，不需要記錄或追蹤。","設備可用度高就表示所有安全風險一定很低"],"optionsEn":["Stagnant pockets may remain concentrated after the average falls.","A crack or anomaly that appears only once can be ignored without logging or follow-up.","High equipment availability necessarily means every safety risk is low."],"answer":0,"explanation":"死角可能在平均濃度下降後仍維持高濃度；風機反轉或風門錯位也會改變流路，不能只用風機啟動回饋判斷通風。 需以量測區分可能原因。","explanationEn":"Stagnant pockets may remain concentrated after the average falls; reversed fans or misplaced dampers alter flow paths, so a running-status signal alone cannot verify ventilation. Discriminate candidate causes by measurement."},"unit":9,"unitFacet":"failure","order":4,"sequence":36},{"id":"b334-v16-37","title":"可用度與修復時間：機制與系統路徑","titleEn":"Availability and repair time: mechanism and system paths","estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-36"],"objective":"說明「可用度與修復時間」如何影響墨爾本地鐵隧道計畫的受力、變形、水流或訊號表現，並畫出相關輸入、傳遞路徑與邊界。","objectiveEn":"Explain how “Availability and repair time” governs forces, deformation, flow or signals in “Melbourne Metro Tunnel project”, and map the relevant inputs, transfer paths and boundaries.","instruction":"在簡化更新過程中，可用度是平均故障間隔占故障間隔加修復時間的比例。這個指標不能替代安全性，因為快速恢復服務可能仍保留危險失效；備品、交通與診斷都會影響實際修復時間。 平均故障間隔和平均修復時間必須使用相同服務邊界；備件等待與到場時間若被排除，數字就不能描述旅客看到的中斷。短期樣本也應報告事件數與觀測時間。 將初期載客與完整班表的故障暴露時間分別統計。 師傅任務：以自由體圖、流路圖或訊號圖畫出相關物理量如何經過「可用度與修復時間」傳到系統邊界，標出哪些量由設計決定、哪些由材料、施工或環境決定，再用三句話寫出機制摘要。","instructionEn":"In a simplified renewal process, availability is mean time between failures divided by that time plus mean repair time. It does not replace safety: rapidly restoring service may leave a hazardous failure unresolved. Spares, travel and diagnosis all affect actual restoration time. Mean time between failures and mean repair time require a common service boundary. Excluding spare-part waiting or travel time prevents the figure from describing passenger-visible interruption. Short samples should also report event count and observation duration. Calculate failure exposure separately for initial passenger service and the complete timetable. Mentor task: draw a free-body, flow or signal diagram showing how relevant physical quantities pass through “Availability and repair time” to the system boundary, mark which quantities are fixed by design and which by materials, construction or environment, then summarise the mechanism in three sentences.","observation":"量級提示：原創假想算例，全部輸入均非本工程操作參數：mtbf=1260 h; mttr=4 h；計算：availability=mtbf/(mtbf+mttr)=0.9968354 1。","observationEn":"Order-of-magnitude cue: Original hypothetical exercise; none of these inputs are operating parameters of this project: mtbf=1260 h; mttr=4 h; calculation: availability=mtbf/(mtbf+mttr)=0.9968354 1.","failure":"常見誤解：「設備可用度高就表示所有安全風險一定很低」這個說法忽略了上述機制；請在系統圖上指出它錯在哪一個環節。","failureEn":"Common misconception: \"High equipment availability necessarily means every safety risk is low.\" It ignores the mechanism above; mark on your system diagram where it breaks down.","check":"系統圖標明「可用度與修復時間」的輸入、傳遞路徑與邊界；三句摘要能解釋本步列出的誤解為何不成立。","checkEn":"The system diagram shows inputs, transfer paths and boundaries for “Availability and repair time”; the three-sentence summary explains why the listed misconception fails.","knowledge":[{"id":"b334-v16-37-k1","title":"可用度與修復時間","titleEn":"Availability and repair time","text":"在簡化更新過程中，可用度是平均故障間隔占故障間隔加修復時間的比例。這個指標不能替代安全性，因為快速恢復服務可能仍保留危險失效；備品、交通與診斷都會影響實際修復時間。","textEn":"In a simplified renewal process, availability is mean time between failures divided by that time plus mean repair time. It does not replace safety: rapidly restoring service may leave a hazardous failure unresolved.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-37-k2","title":"誤解辨析","titleEn":"Misconception check","text":"誤解：設備可用度高就表示所有安全風險一定很低 正確的工程判斷必須回到傳力機制與量級。","textEn":"Misconception: High equipment availability necessarily means every safety risk is low. Sound engineering judgement goes back to the load path and magnitude.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"關於「可用度與修復時間」，下列哪一項敘述正確？","questionEn":"Which statement about \"Availability and repair time\" is correct?","options":["設備可用度高就表示所有安全風險一定很低","在簡化更新過程中，可用度是平均故障間隔占故障間隔加修復時間的比例。","施工窗口全長都可以直接乘以施工速度當成可完成量"],"optionsEn":["High equipment availability necessarily means every safety risk is low.","In a simplified renewal process, availability is mean time between failures divided by that time plus mean repair time.","The entire possession duration can be multiplied by work rate to obtain achievable production."],"answer":1,"explanation":"在簡化更新過程中，可用度是平均故障間隔占故障間隔加修復時間的比例。 其餘選項是常見誤解。","explanationEn":"In a simplified renewal process, availability is mean time between failures divided by that time plus mean repair time. The other options are common misconceptions."},"unit":10,"unitFacet":"mechanism","order":5,"sequence":37},{"id":"b334-v16-38","title":"可用度與修復時間：定量估算","titleEn":"Availability and repair time: quantitative estimate","estimatedMinutes":30,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-37"],"objective":"以數值模型估算「可用度與修復時間」的關鍵量，並判斷幾何、速度、荷載或材料參數改變時結果的方向與幅度。","objectiveEn":"Estimate the key quantities of “Availability and repair time” with a numerical model and judge the direction and size of change when geometry, speed, load or material parameters move.","instruction":"依下列模型逐步重算：原創假想算例，全部輸入均非本工程操作參數：mtbf=1260 h; mttr=4 h；計算：availability=mtbf/(mtbf+mttr)=0.9968354 1。敏感度：mtbf 單獨增加百分之十至 1386 h，其餘固定，結果為 0.9971223 1。模型邊界：兩狀態穩態平均模型；不含計畫維修、共同原因與降級服務品質。 師傅任務：保留單位重算一次，再只改變一個輸入（連續量可增加 10%；計數須保持整數；分貝量使用加減值），預測並計算輸出的變化，說明它是線性、平方或更高次方的關係，並指出規範或設計上通常如何處理這個敏感度。","instructionEn":"Recalculate step by step: Original hypothetical exercise; none of these inputs are operating parameters of this project: mtbf=1260 h; mttr=4 h; calculation: availability=mtbf/(mtbf+mttr)=0.9968354 1. Sensitivity: mtbf, increase this input alone by ten percent, to 1386 h, with all other inputs fixed, gives 0.9971223 1. Model boundary: Two-state steady-state mean model; planned maintenance, common causes and degraded service quality are excluded. Mentor task: redo the calculation keeping units, then change one input (for example +10% for a continuous quantity; retain integers for counts and use additive changes for decibels), predict and compute the output change, state whether the dependence is linear, quadratic or steeper, and note how codes or designers usually handle this sensitivity.","observation":"如何核對：將故障開始、到場、診斷、修復及恢復服務分段記錄，明確定義可用狀態，避免把降級運轉與完整服務混算。","observationEn":"How to cross-check: Record failure onset, arrival, diagnosis, repair and service restoration separately, define the available state, and avoid mixing degraded operation with full service.","failure":"計算陷阱：單位換算錯誤、把教學假設當成真實設計值、混淆標稱值與設計值（未乘載重或強度係數），或只看結果不檢查數量級，都會讓後續設計判斷失準。","failureEn":"Calculation traps: unit slips, treating teaching assumptions as real design values, mixing nominal and factored values, or accepting a result without checking its magnitude will mislead later design decisions.","check":"依模型顯示精度重現數值，列出單位與取整方式，並提交一個參數改變後的敏感度計算與工程解釋。","checkEn":"Reproduce the model values to their displayed precision, state units and rounding, and submit a sensitivity calculation for one changed parameter with an engineering explanation.","knowledge":[{"id":"b334-v16-38-k1","title":"定量模型","titleEn":"Quantitative model","text":"原創假想算例，全部輸入均非本工程操作參數：mtbf=1260 h; mttr=4 h；計算：availability=mtbf/(mtbf+mttr)=0.9968354 1。敏感度：mtbf 單獨增加百分之十至 1386 h，其餘固定，結果為 0.9971223 1。模型邊界：兩狀態穩態平均模型；不含計畫維修、共同原因與降級服務品質。","textEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: mtbf=1260 h; mttr=4 h; calculation: availability=mtbf/(mtbf+mttr)=0.9968354 1. Sensitivity: mtbf, increase this input alone by ten percent, to 1386 h, with all other inputs fixed, gives 0.9971223 1. Model boundary: Two-state steady-state mean model; planned maintenance, common causes and degraded service quality are excluded.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-38-k2","title":"模型邊界","titleEn":"Model boundary","text":"本步數值為教學假設或公開資料的簡化；套用到實際工程前，必須依規範荷載組合、材料試驗與現場量測重新計算並由技師簽證。","textEn":"These numbers are teaching assumptions or simplified public data; before applying them to a real system, recalculate with code load combinations, material tests and site measurements, certified by a qualified engineer.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"依「可用度與修復時間」的定量模型，下列哪一項敘述成立？","questionEn":"According to the quantitative model for \"Availability and repair time\", which statement holds?","options":["兩端高程相同就能證明兩點之間沒有差異沉陷","聯鎖只要正常路徑通過測試就不需要檢查衝突請求","原創假想算例，全部輸入均非本工程操作參數：mtbf=1260 h; mttr=4 h。"],"optionsEn":["Equal endpoint elevations prove there is no differential settlement between them.","Passing normal route tests removes the need to test conflicting requests.","Original hypothetical exercise."],"answer":2,"explanation":"原創假想算例，全部輸入均非本工程操作參數：mtbf=1260 h; mttr=4 h；計算：availability=mtbf/(mtbf+mttr)=0.9968354 1。 重算時請保留單位。","explanationEn":"Original hypothetical exercise; none of these inputs are operating parameters of this project: mtbf=1260 h; mttr=4 h; calculation: availability=mtbf/(mtbf+mttr)=0.9968354 1. Keep units when recalculating."},"unit":10,"unitFacet":"model","order":6,"sequence":38},{"id":"b334-v16-39","title":"可用度與修復時間：試驗與驗證","titleEn":"Availability and repair time: testing and verification","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-38"],"objective":"設計一項可重複的試驗、量測或檢查，驗證「可用度與修復時間」是否符合模型與規範預期，並在量測前訂出允收準則與停工點。","objectiveEn":"Design a repeatable test, measurement or inspection that verifies whether “Availability and repair time” meets the model and code expectation, fixing acceptance criteria and hold points before measuring.","instruction":"將故障開始、到場、診斷、修復及恢復服務分段記錄，明確定義可用狀態，避免把降級運轉與完整服務混算。 逐項對照故障開始、服務恢復與維修完成時間，公開排除項，並核對總觀測時數。 師傅任務：把上述方法寫成試驗或量測計畫，列出儀器與感測器、基準點或參考試體、步驟、比較對象、允收準則與停工點，並估計三項主要不確定度來源。","instructionEn":"Record failure onset, arrival, diagnosis, repair and service restoration separately, define the available state, and avoid mixing degraded operation with full service. Cross-check fault start, service restoration and repair completion for each event, disclose exclusions, and verify total observed hours. Mentor task: turn this into a test or measurement plan listing instruments and sensors, datums or reference specimens, procedure, comparison baseline, acceptance criteria and hold points, and estimate the three largest uncertainty contributions.","observation":"現場實務：比較提高故障間隔與縮短修復時間兩種措施，用同一故障定義重算，並列出可用度之外需要追蹤的危險失效指標。 再以本單元 mtbf 的對照值重算 availability，提交含單位、輸入來源和模型不適用條件的結果表。","observationEn":"Site practice: Compare increasing failure interval with reducing repair time under one failure definition, and list hazardous-failure measures that must be tracked separately from availability. Also recalculate availability for the alternative mtbf value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","failure":"注意干擾：只縮短更換時間但備品仍缺貨，可用度未必改善；將延後報修時間排除也會讓數字看似漂亮卻失去代表性。 只量一次、沒有可追溯的基準，或不記錄溫度、速度與操作條件，就無法分辨真正的偏差與量測誤差。","failureEn":"Watch for interference: Shorter replacement time may not improve availability when spare parts remain unavailable; excluding reporting delays can also create an unrepresentative figure. A single reading, no traceable datum, or unrecorded temperature, speed and operating conditions make real deviations indistinguishable from measurement error.","check":"提交試驗或量測計畫：儀器、基準、步驟、允收準則、停工點與不確定度預算，並說明如何判定合格或不合格、由誰簽認。","checkEn":"Submit the test or measurement plan: instruments, datums, procedure, acceptance criteria, hold points and uncertainty budget, with the pass/fail rule and who signs it off.","knowledge":[{"id":"b334-v16-39-k1","title":"驗證方法","titleEn":"Verification method","text":"將故障開始、到場、診斷、修復及恢復服務分段記錄，明確定義可用狀態，避免把降級運轉與完整服務混算。 逐項對照故障開始、服務恢復與維修完成時間，公開排除項，並核對總觀測時數。","textEn":"Record failure onset, arrival, diagnosis, repair and service restoration separately, define the available state, and avoid mixing degraded operation with full service. Cross-check fault start, service restoration and repair completion for each event, disclose exclusions, and verify total observed hours.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-39-k2","title":"現場實務","titleEn":"Site practice","text":"比較提高故障間隔與縮短修復時間兩種措施，用同一故障定義重算，並列出可用度之外需要追蹤的危險失效指標。 再以本單元 mtbf 的對照值重算 availability，提交含單位、輸入來源和模型不適用條件的結果表。","textEn":"Compare increasing failure interval with reducing repair time under one failure definition, and list hazardous-failure measures that must be tracked separately from availability. Also recalculate availability for the alternative mtbf value in this unit, submitting units, input provenance and conditions under which the model is inapplicable.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"要驗證「可用度與修復時間」，下列哪一個做法最恰當？","questionEn":"Which approach best verifies \"Availability and repair time\"?","options":["將故障開始、到場、診斷、修復及恢復服務分段記錄，明確定義可用狀態，避免把降級運轉與完整服務混算。","不確定度太難估計，報告中只寫最佳值即可。","降低目標速度時可忽略初速與目標速度的平方差"],"optionsEn":["Record failure onset, arrival, diagnosis, repair and service restoration separately, define the available state, and avoid mixing degraded operation with full service.","Uncertainty is too hard to estimate, so the report may state only the best value.","Reducing target speed allows the squared-speed difference to be ignored."],"answer":0,"explanation":"將故障開始、到場、診斷、修復及恢復服務分段記錄，明確定義可用狀態，避免把降級運轉與完整服務混算。 驗證需要基準、重複性與事先訂定的允收準則。","explanationEn":"Record failure onset, arrival, diagnosis, repair and service restoration separately, define the available state, and avoid mixing degraded operation with full service. Verification needs a datum, repeatability and acceptance criteria fixed in advance."},"unit":10,"unitFacet":"verification","order":7,"sequence":39},{"id":"b334-v16-40","title":"可用度與修復時間：失效診斷","titleEn":"Availability and repair time: failure diagnosis","estimatedMinutes":25,"simulationOnly":true,"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"prerequisiteIds":["b334-v16-39"],"objective":"從症狀倒推「可用度與修復時間」的失效或劣化原因，提出能區分原因的檢查、矯正與預防措施。","objectiveEn":"Work back from symptoms to the failure or deterioration causes of “Availability and repair time” and propose discriminating checks, corrective actions and prevention.","instruction":"只縮短更換時間但備品仍缺貨，可用度未必改善；將延後報修時間排除也會讓數字看似漂亮卻失去代表性。 修好設備和恢復服務可能不同時，須分別記錄終點。 師傅任務：建立失效樹——症狀、兩個以上可能原因、能區分它們的量測或檢測，以及矯正與預防措施；並說明此失效如何影響整體系統的安全、使用性、耐久或營運。","instructionEn":"Shorter replacement time may not improve availability when spare parts remain unavailable; excluding reporting delays can also create an unrepresentative figure. Equipment repair and service restoration may occur at different times; record both endpoints. Mentor task: build a fault tree with the symptom, at least two candidate causes, a measurement or inspection that tells them apart, and corrective and preventive actions; explain how the failure affects whole-system safety, serviceability, durability or operation.","observation":"連結機制：將初期載客與完整班表的故障暴露時間分別統計。","observationEn":"Link to the mechanism: Calculate failure exposure separately for initial passenger service and the complete timetable.","failure":"誤判風險：若相信「設備可用度高就表示所有安全風險一定很低」，上述症狀可能被錯誤處理而反覆出現。","failureEn":"Misdiagnosis risk: believing \"High equipment availability necessarily means every safety risk is low.\" leads to mishandling the symptom so it keeps returning.","check":"完成失效樹與矯正措施，指出哪一項量測或檢測能最快確認根因、需要哪些人簽認，以及如何防止再發。","checkEn":"Complete the fault tree and corrective actions, name the measurement or inspection that confirms the root cause fastest, who must sign off, and how recurrence is prevented.","knowledge":[{"id":"b334-v16-40-k1","title":"失效模式","titleEn":"Failure mode","text":"只縮短更換時間但備品仍缺貨，可用度未必改善；將延後報修時間排除也會讓數字看似漂亮卻失去代表性。 修好設備和恢復服務可能不同時，須分別記錄終點。","textEn":"Shorter replacement time may not improve availability when spare parts remain unavailable; excluding reporting delays can also create an unrepresentative figure. Equipment repair and service restoration may occur at different times; record both endpoints.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]},{"id":"b334-v16-40-k2","title":"根因確認","titleEn":"Root-cause confirmation","text":"根因必須以可區分的量測或檢測確認；只補強外觀、更換構件或放寬允收值可能掩蓋問題。","textEn":"Confirm the root cause with a discriminating measurement or inspection; cosmetic repair, swapping components or relaxing limits can mask the problem.","sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"]}],"quiz":{"question":"在「可用度與修復時間」出現異常時，下列哪一項判斷最合理？","questionEn":"When \"Availability and repair time\" shows distress, which diagnosis is most reasonable?","options":["先更換最貴的構件；只要症狀消失，就代表已找到根因。","只縮短更換時間但備品仍缺貨，可用度未必改善；將延後報修時間排除也會讓數字看似漂亮卻失去代表性。","施工窗口全長都可以直接乘以施工速度當成可完成量"],"optionsEn":["Replace the most expensive component first; if the symptom disappears, the root cause has been found.","Shorter replacement time may not improve availability when spare parts remain unavailable.","The entire possession duration can be multiplied by work rate to obtain achievable production."],"answer":1,"explanation":"只縮短更換時間但備品仍缺貨，可用度未必改善；將延後報修時間排除也會讓數字看似漂亮卻失去代表性。 需以量測區分可能原因。","explanationEn":"Shorter replacement time may not improve availability when spare parts remain unavailable; excluding reporting delays can also create an unrepresentative figure. Discriminate candidate causes by measurement."},"unit":10,"unitFacet":"failure","order":8,"sequence":40}],"order":5}],"sourceIds":["v16s-b334-history","v16s-b301-iec-rams-1","v16s-b301-iec-rams-2","v16s-b334-background"],"curriculumVersion":16,"stepCount":40,"estimatedMinutes":1000,"flowDiagram":"assets/diagrams/v16-b334-zh.svg","flowDiagramEn":"assets/diagrams/v16-b334-en.svg"}};
